/************************************************************
ARCHR Eligibility Report Email Renderer — Airtable-safe version

Uses individual triage fields:
- triageScore
- triageMessage
- triageDemo
- triageCategoriesRaw
- triageWait

Also supports:
- claimsRaw: "(5/13/2026) | 🪝Claimed | AAHH"

Inputs:
- subjectTemplate
- headTemplate
- bodyTemplate
- reportItemsJSON
- reportName
- reportOrg
- reportStart
- reportEnd

Outputs:
- subject
- html
- text
- reportCount
************************************************************/

const config = input.config();

/************************************************************
INPUT HELPERS
************************************************************/

function getConfig(names, fallback = "") {
    for (const name of names) {
        if (Object.prototype.hasOwnProperty.call(config, name)) {
            const value = config[name];
            if (value !== undefined && value !== null && value !== "") return value;
        }
    }
    return fallback;
}

function first(value) {
    if (Array.isArray(value)) return value[0] ?? "";
    return value ?? "";
}

const subjectTemplate = String(first(getConfig([
    "subjectTemplate",
    "Subject",
    "subject"
])) || "");

const headTemplate = String(first(getConfig([
    "headTemplate",
    "Head",
    "head"
])) || "");

const bodyTemplate = String(first(getConfig([
    "bodyTemplate",
    "Body",
    "body"
])) || "");

const reportItemsRaw = getConfig([
    "reportItemsJSON",
    "reportsJSON",
    "emailReportJSON",
    "📨emailReportJSON",
    "✅reportRollup",
    "reportJsonRollup"
]);

const reportName = String(first(getConfig([
    "reportName",
    "recipientName",
    "name"
])) || "team");

const reportOrg = String(first(getConfig([
    "reportOrg",
    "organization",
    "org"
])) || "Partner");

const reportStart = String(first(getConfig([
    "reportStart",
    "startDate",
    "periodStart"
])) || "");

const reportEnd = String(first(getConfig([
    "reportEnd",
    "endDate",
    "periodEnd"
])) || "");

/************************************************************
TEXT / HTML HELPERS
************************************************************/

function normalizeText(value) {
    return String(value ?? "")
        .replace(/\\n/g, "\n")
        .replace(/\r\n/g, "\n")
        .trim();
}

function htmlEscape(value) {
    return String(value ?? "")
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#039;");
}

function attrEscape(value) {
    return htmlEscape(value).replaceAll("`", "&#096;");
}

function splitLines(value) {
    return normalizeText(value)
        .split(/\n+/)
        .map(v => v.trim())
        .filter(Boolean);
}

function splitCsvish(value) {
    return normalizeText(value)
        .split(/,|\n/)
        .map(v => v.trim())
        .filter(Boolean);
}

function cleanProgramName(value) {
    return String(value ?? "")
        .replace(/\s*✅\s*$/g, "")
        .replace(/\s*❌\s*$/g, "")
        .trim();
}

function extractUrl(value) {
    const s = String(value ?? "");

    const md = s.match(/\(\{?(https?:\/\/[^)\s}]+)/i);
    if (md) return md[1];

    const plain = s.match(/https?:\/\/[^\s)}/]+/i);
    if (plain) return plain[0];

    return "";
}

function replaceTokens(template, tokens) {
    let out = String(template ?? "");

    for (const [key, value] of Object.entries(tokens)) {
        out = out.split(`{{${key}}}`).join(value ?? "");
    }

    return out;
}

function stripHtmlToText(value) {
    return String(value ?? "")
        .replace(/<br\s*\/?>/gi, "\n")
        .replace(/<\/p>/gi, "\n")
        .replace(/<[^>]+>/g, "")
        .replace(/&amp;/g, "&")
        .replace(/&lt;/g, "<")
        .replace(/&gt;/g, ">")
        .replace(/&quot;/g, '"')
        .replace(/&#039;/g, "'")
        .replace(/\n{3,}/g, "\n\n")
        .trim();
}

/************************************************************
DATE HELPERS
************************************************************/

function cleanAgeLabel(value) {
    const s = String(value ?? "").trim();

    if (!s) return "";

    const doubleParen = s.match(/^\(\((.*)\)\)$/);
    if (doubleParen) return `(${doubleParen[1].trim()})`;

    return s;
}

function formatSubmittedDate(value, ageLabel = "") {
    const raw = String(value ?? "").trim();
    const age = cleanAgeLabel(ageLabel);

    if (!raw) return age || "";

    const d = new Date(raw);

    if (Number.isNaN(d.getTime())) {
        return [raw, age].filter(Boolean).join(" ");
    }

    const formatted = new Intl.DateTimeFormat("en-US", {
        timeZone: "UTC",
        month: "numeric",
        day: "numeric",
        year: "numeric"
    }).format(d);

    return [formatted, age].filter(Boolean).join(" ");
}

/************************************************************
AIRTABLE-SAFE TEMPLATE CONVERSION
************************************************************/

function templateTextToAirtableHtml(value) {
    let s = String(value ?? "")
        .replace(/\r\n/g, "\n")
        .replace(/\\n/g, "\n");

    s = s.replace(/^###\s+(.*)$/gm, '<span style="font-size:16px;"><strong>$1</strong></span>');
    s = s.replace(/^##\s+(.*)$/gm, '<span style="font-size:18px;"><strong>$1</strong></span>');
    s = s.replace(/^#\s+(.*)$/gm, '<span style="font-size:20px;"><strong>$1</strong></span>');

    s = s.replace(/\*\*(.*?)\*\*/g, "<strong>$1</strong>");

    s = s.replace(/\[([^\]]+)\]\(\{?(https?:\/\/[^)\s}]+)\}?\)/g, '<a href="$2">$1</a>');

    s = s.replace(/\n/g, "<br>");

    return s;
}

function fieldTextToAirtableHtml(value) {
    let s = String(value ?? "")
        .replace(/\\n/g, "\n")
        .replace(/\r\n/g, "\n");

    s = htmlEscape(s);

    s = s.replace(/^###\s+(.*)$/gm, '<span style="font-size:16px;"><strong>$1</strong></span>');
    s = s.replace(/^##\s+(.*)$/gm, '<span style="font-size:18px;"><strong>$1</strong></span>');
    s = s.replace(/^#\s+(.*)$/gm, '<span style="font-size:20px;"><strong>$1</strong></span>');
    s = s.replace(/\*\*(.*?)\*\*/g, "<strong>$1</strong>");
    s = s.replace(/\n/g, "<br>");

    return s;
}

/************************************************************
JSON REPAIR + PARSING
************************************************************/

function escapeRawControlCharsInsideJsonStrings(input) {
    const s = String(input ?? "");
    let out = "";
    let inString = false;
    let escaped = false;

    for (let i = 0; i < s.length; i++) {
        const ch = s[i];

        if (escaped) {
            out += ch;
            escaped = false;
            continue;
        }

        if (ch === "\\") {
            out += ch;
            escaped = true;
            continue;
        }

        if (ch === '"') {
            inString = !inString;
            out += ch;
            continue;
        }

        if (inString) {
            if (ch === "\n") {
                out += "\\n";
                continue;
            }

            if (ch === "\r") {
                out += "\\r";
                continue;
            }

            if (ch === "\t") {
                out += "\\t";
                continue;
            }

            const code = ch.charCodeAt(0);
            if (code >= 0 && code <= 31) {
                out += "\\u" + code.toString(16).padStart(4, "0");
                continue;
            }
        }

        out += ch;
    }

    return out;
}

function parseReportItems(raw) {
    if (Array.isArray(raw)) {
        const cleanedArray = raw
            .map(v => {
                if (typeof v === "object" && v !== null) return v;
                return String(v ?? "").trim();
            })
            .filter(Boolean);

        if (!cleanedArray.length) return [];

        if (typeof cleanedArray[0] === "object") return cleanedArray;

        return parseReportItems(cleanedArray.join(","));
    }

    let clean = String(raw ?? "").trim();

    if (!clean) return [];

    clean = escapeRawControlCharsInsideJsonStrings(clean);

    try {
        if (clean.startsWith("[") && clean.endsWith("]")) {
            return JSON.parse(clean);
        }

        if (clean.startsWith("{") && clean.endsWith("}")) {
            return JSON.parse(`[${clean}]`);
        }

        return JSON.parse(`[${clean}]`);

    } catch (err) {
        throw new Error(
            [
                "Could not parse reportItemsJSON.",
                "",
                "Most likely causes:",
                "1. A double quote in an Airtable formula output was not escaped.",
                "2. Your rollup is not joining JSON objects with commas.",
                "3. A field contains malformed markdown/link syntax.",
                "",
                `Parse error: ${err.message}`,
                "",
                "Raw input starts with:",
                String(raw ?? "").slice(0, 1000),
                "",
                "Sanitized input starts with:",
                clean.slice(0, 1000)
            ].join("\n")
        );
    }
}

/************************************************************
CLAIMS
************************************************************/

function parseClaims(value) {
    if (Array.isArray(value)) {
        return value
            .map(v => String(v ?? "").trim())
            .filter(Boolean);
    }

    const s = normalizeText(value);
    if (!s) return [];

    let parts = s.split(/\n+/).map(v => v.trim()).filter(Boolean);

    if (parts.length === 1 && parts[0].match(/\(\d{1,2}\/\d{1,2}\/\d{4}\)/g)?.length > 1) {
        parts = parts[0]
            .split(/,\s*(?=\(\d{1,2}\/\d{1,2}\/\d{4}\)\s*\|)/)
            .map(v => v.trim())
            .filter(Boolean);
    }

    return parts;
}

/************************************************************
ITEM NORMALIZATION
************************************************************/

function prepareItem(item) {
    const rawEligible =
        item.eligibleProgramsRaw ??
        item.eligiblePrograms ??
        item["💛✅Eligible for Programs"] ??
        "";

    const rawIneligible =
        item.ineligibleProgramsRaw ??
        item.ineligiblePrograms ??
        item["💛❌Ineligible for Programs"] ??
        "";

    const rawCategories =
        item.triageCategoriesRaw ??
        item.triageCategories ??
        item["❗Triage 🛠️Request Categories"] ??
        "";

    let eligiblePrograms = [];

    if (Array.isArray(rawEligible)) {
        eligiblePrograms = rawEligible.map(cleanProgramName).filter(Boolean);
    } else {
        eligiblePrograms = splitLines(rawEligible).length
            ? splitLines(rawEligible).map(cleanProgramName).filter(Boolean)
            : splitCsvish(rawEligible).map(cleanProgramName).filter(Boolean);
    }

    let ineligiblePrograms = [];

    if (Array.isArray(rawIneligible)) {
        ineligiblePrograms = rawIneligible.map(cleanProgramName).filter(Boolean);
    } else {
        ineligiblePrograms = splitLines(rawIneligible).length
            ? splitLines(rawIneligible).map(cleanProgramName).filter(Boolean)
            : splitCsvish(rawIneligible).map(cleanProgramName).filter(Boolean);
    }

    const triageCategories = Array.isArray(rawCategories)
        ? rawCategories.map(v => String(v ?? "").trim()).filter(Boolean)
        : splitCsvish(rawCategories);

    const claimsRaw =
        item.claimsRaw ??
        item.claims ??
        item["🪝Claims"] ??
        item["Claims"] ??
        "";

    const propertyCardRaw =
        item.propertyCardRaw ??
        item.propertyCard ??
        item["Property Card "] ??
        item["Property Card"] ??
        "";

    const reviewRaw =
        item.reviewRaw ??
        item.reviewUrl ??
        item["📨Review Button"] ??
        "";

    return {
        id: item.id ?? item.recordId ?? "",
        oneLine: item.oneLine ?? item["✅Report"] ?? "",
        applicant: item.applicant ?? item["👤Applicant Full Name"] ?? "",
        address: item.address ?? item["📍Address"] ?? "",
        unit: item.unit ?? item["📍Unit"] ?? "",
        cityCheck: item.cityCheck ?? item["📍City of Asheville"] ?? "",
        neighborhood: item.neighborhood ?? item["📍Neighborhood"] ?? "",
        placeCode: item.placeCode ?? item["⚓📍PlaceCode"] ?? "",
        label: item.label ?? item["⚓🎯 Label"] ?? "",
        ami: item.ami ?? item["👤AMI%"] ?? "",
        submitted: item.submitted ?? item["📅Submission Date"] ?? "",
        submissionAge: item.submissionAge ?? item["🕰️Submission Age"] ?? "",

        eligiblePrograms,
        ineligiblePrograms,

        triageScore:
            item.triageScore ??
            item["❗Triage Score"] ??
            "",

        triageMessage:
            item.triageMessage ??
            item["❗Triage Message"] ??
            "",

        triageDemo:
            item.triageDemo ??
            item["❗Triage Demo"] ??
            "",

        triageCategories,

        triageWait:
            item.triageWait ??
            item["❗Triage 🕰️Wait time"] ??
            "",

        claims: parseClaims(claimsRaw),

        propertyCardRaw,
        reviewRaw,

        propertyCardUrl:
            item.propertyCardUrl ||
            extractUrl(propertyCardRaw),

        reviewUrl:
            item.reviewUrl ||
            extractUrl(reviewRaw)
    };
}

/************************************************************
EMAIL SECTION RENDERERS — AIRTABLE SAFE HTML
************************************************************/

function renderTopLineList(items) {
    if (!items.length) {
        return "<em>No matching reports found.</em><br>";
    }

    return items.map((item, i) => {
        const label = item.oneLine || `${item.applicant || "Unnamed applicant"} — ${item.address || ""}`;
        const review = item.reviewUrl
            ? ` <a href="${attrEscape(item.reviewUrl)}">Review</a>`
            : "";

        return `${i + 1}. ${htmlEscape(label)}${review}`;
    }).join("<br>");
}

function renderDetailCard(item, index) {
    const eligible = item.eligiblePrograms?.length
        ? item.eligiblePrograms.map(p => `✅ ${htmlEscape(p)}`).join("<br>")
        : "<em>None listed</em>";

    const ineligible = item.ineligiblePrograms?.length
        ? "<br><br><strong>Ineligible programs</strong><br>" +
          item.ineligiblePrograms.map(p => `❌ ${htmlEscape(p)}`).join("<br>")
        : "";

    const categories = item.triageCategories?.length
        ? item.triageCategories.map(c => htmlEscape(c)).join(", ")
        : "None listed";

    const claimsHtml = item.claims?.length
        ? "<br><br><strong>Claim status</strong><br>" +
          item.claims.map(c => `🪝 ${htmlEscape(c)}`).join("<br>")
        : "";

    const triageMessageHtml = item.triageMessage
        ? `<br><br><strong>Triage calculation</strong><br>${fieldTextToAirtableHtml(item.triageMessage)}`
        : "";

    const reviewLink = item.reviewUrl
        ? `<a href="${attrEscape(item.reviewUrl)}">Open Review Page</a>`
        : "";

    const propCardLink = item.propertyCardUrl
        ? `<a href="${attrEscape(item.propertyCardUrl)}">Property Card</a>`
        : "";

    const links = [reviewLink, propCardLink].filter(Boolean).join(" | ");

    const addressLine = [
        item.address ? htmlEscape(item.address) : "",
        item.unit ? `Unit ${htmlEscape(item.unit)}` : ""
    ].filter(Boolean).join(", ");

    return [
        "<br>",
        `<span style="font-size:18px;"><strong>${index + 1}. ${htmlEscape(item.applicant || "Unnamed applicant")}</strong></span>`,
        "<br>",
        addressLine || "<em>No address listed</em>",
        item.placeCode ? `<br>PlaceCode: ${htmlEscape(item.placeCode)}` : "",
        item.label ? `<br>Label: ${htmlEscape(item.label)}` : "",
        "<br><br>",

        `<strong>Triage Score:</strong> ${htmlEscape(item.triageScore || "—")}`,
        "<br>",
        `<strong>Submitted:</strong> ${htmlEscape(formatSubmittedDate(item.submitted, item.submissionAge) || "—")}`,
        "<br>",
        `<strong>AMI:</strong> ${htmlEscape(item.ami || "—")}`,
        "<br>",
        `<strong>City Check:</strong> ${htmlEscape(item.cityCheck || "—")}`,
        "<br>",
        `<strong>Neighborhood:</strong> ${htmlEscape(item.neighborhood || "—")}`,
        "<br>",
        `<strong>Wait Factor:</strong> ${htmlEscape(item.triageWait || "—")}`,
        "<br><br>",

        "<strong>Eligible programs</strong>",
        "<br>",
        eligible,
        ineligible,

        "<br><br>",
        "<strong>Request / triage categories</strong>",
        "<br>",
        categories,

        claimsHtml,

        item.triageDemo
            ? `<br><br><strong>Demographic triage notes</strong><br>${htmlEscape(item.triageDemo)}`
            : "",

        triageMessageHtml,

        links ? `<br><br>${links}` : "",

        "<br><br>",
        '<span style="color:#999999;">────────────────────────</span>',
        "<br>"
    ].join("");
}

/************************************************************
MAIN
************************************************************/

let items = parseReportItems(reportItemsRaw).map(prepareItem);

// Highest triage score first.
// Remove this sort if you want Airtable linked-record order preserved.
items.sort((a, b) => Number(b.triageScore || 0) - Number(a.triageScore || 0));

const reportCount = items.length;
const reportCountLabel = `${reportCount} ${reportCount === 1 ? "Submission" : "Submissions"}`;

const topLineHtml = renderTopLineList(items);
const detailHtml = items.map(renderDetailCard).join("<br>");

const tokens = {
    reportCount: String(reportCount),
    reportCountLabel,
    reportName,
    reportOrg,
    reportStart,
    reportEnd,

    "✅reportRollup": topLineHtml,
    "✅longerApplicantSummary (from the CSV)": detailHtml,

    reportRollup: topLineHtml,
    longerApplicantSummary: detailHtml,
    applicantSummary: detailHtml
};

const subject = replaceTokens(subjectTemplate, {
    ...tokens,

    "✅reportRollup": "",
    "✅longerApplicantSummary (from the CSV)": "",
    reportRollup: "",
    longerApplicantSummary: "",
    applicantSummary: ""
})
    .replace(/\s+/g, " ")
    .trim();

const renderedHead = replaceTokens(headTemplate, tokens);
const renderedBody = replaceTokens(bodyTemplate, tokens);

const html = [
    templateTextToAirtableHtml(renderedHead),
    "<br><br>",
    templateTextToAirtableHtml(renderedBody)
].join("");

const text = stripHtmlToText(html);

output.set("subject", subject);
output.set("html", html);
output.set("text", text);
output.set("reportCount", reportCount);

output.set("debugFirstApplicant", items[0]?.applicant || "");
output.set("debugFirstReviewUrl", items[0]?.reviewUrl || "");
output.set("debugFirstTriageScore", items[0]?.triageScore || "");
output.set("debugFirstClaims", items[0]?.claims?.join(" | ") || "");

script:
/************************************************************
ARCHR Eligibility Report Email Renderer — Airtable-safe version

Uses individual triage fields:
- triageScore
- triageMessage
- triageDemo
- triageCategoriesRaw
- triageWait

Also supports:
- claimsRaw: "(5/13/2026) | 🪝Claimed | AAHH"

Inputs:
- subjectTemplate
- headTemplate
- bodyTemplate
- reportItemsJSON
- reportName
- reportOrg
- reportStart
- reportEnd

Outputs:
- subject
- html
- text
- reportCount
************************************************************/

const config = input.config();

/************************************************************
INPUT HELPERS
************************************************************/

function getConfig(names, fallback = "") {
    for (const name of names) {
        if (Object.prototype.hasOwnProperty.call(config, name)) {
            const value = config[name];
            if (value !== undefined && value !== null && value !== "") return value;
        }
    }
    return fallback;
}

function first(value) {
    if (Array.isArray(value)) return value[0] ?? "";
    return value ?? "";
}

const subjectTemplate = String(first(getConfig([
    "subjectTemplate",
    "Subject",
    "subject"
])) || "");

const headTemplate = String(first(getConfig([
    "headTemplate",
    "Head",
    "head"
])) || "");

const bodyTemplate = String(first(getConfig([
    "bodyTemplate",
    "Body",
    "body"
])) || "");

const reportItemsRaw = getConfig([
    "reportItemsJSON",
    "reportsJSON",
    "emailReportJSON",
    "📨emailReportJSON",
    "✅reportRollup",
    "reportJsonRollup"
]);

const reportName = String(first(getConfig([
    "reportName",
    "recipientName",
    "name"
])) || "team");

const reportOrg = String(first(getConfig([
    "reportOrg",
    "organization",
    "org"
])) || "Partner");

const reportStart = String(first(getConfig([
    "reportStart",
    "startDate",
    "periodStart"
])) || "");

const reportEnd = String(first(getConfig([
    "reportEnd",
    "endDate",
    "periodEnd"
])) || "");

/************************************************************
TEXT / HTML HELPERS
************************************************************/

function normalizeText(value) {
    return String(value ?? "")
        .replace(/\\n/g, "\n")
        .replace(/\r\n/g, "\n")
        .trim();
}

function htmlEscape(value) {
    return String(value ?? "")
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#039;");
}

function attrEscape(value) {
    return htmlEscape(value).replaceAll("`", "&#096;");
}

function splitLines(value) {
    return normalizeText(value)
        .split(/\n+/)
        .map(v => v.trim())
        .filter(Boolean);
}

function splitCsvish(value) {
    return normalizeText(value)
        .split(/,|\n/)
        .map(v => v.trim())
        .filter(Boolean);
}

function cleanProgramName(value) {
    return String(value ?? "")
        .replace(/\s*✅\s*$/g, "")
        .replace(/\s*❌\s*$/g, "")
        .trim();
}

function extractUrl(value) {
    const s = String(value ?? "");

    const md = s.match(/\(\{?(https?:\/\/[^)\s}]+)/i);
    if (md) return md[1];

    const plain = s.match(/https?:\/\/[^\s)}/]+/i);
    if (plain) return plain[0];

    return "";
}

function replaceTokens(template, tokens) {
    let out = String(template ?? "");

    for (const [key, value] of Object.entries(tokens)) {
        out = out.split(`{{${key}}}`).join(value ?? "");
    }

    return out;
}

function stripHtmlToText(value) {
    return String(value ?? "")
        .replace(/<br\s*\/?>/gi, "\n")
        .replace(/<\/p>/gi, "\n")
        .replace(/<[^>]+>/g, "")
        .replace(/&amp;/g, "&")
        .replace(/&lt;/g, "<")
        .replace(/&gt;/g, ">")
        .replace(/&quot;/g, '"')
        .replace(/&#039;/g, "'")
        .replace(/\n{3,}/g, "\n\n")
        .trim();
}

/************************************************************
DATE HELPERS
************************************************************/

function cleanAgeLabel(value) {
    const s = String(value ?? "").trim();

    if (!s) return "";

    const doubleParen = s.match(/^\(\((.*)\)\)$/);
    if (doubleParen) return `(${doubleParen[1].trim()})`;

    return s;
}

function formatSubmittedDate(value, ageLabel = "") {
    const raw = String(value ?? "").trim();
    const age = cleanAgeLabel(ageLabel);

    if (!raw) return age || "";

    const d = new Date(raw);

    if (Number.isNaN(d.getTime())) {
        return [raw, age].filter(Boolean).join(" ");
    }

    const formatted = new Intl.DateTimeFormat("en-US", {
        timeZone: "UTC",
        month: "numeric",
        day: "numeric",
        year: "numeric"
    }).format(d);

    return [formatted, age].filter(Boolean).join(" ");
}

/************************************************************
AIRTABLE-SAFE TEMPLATE CONVERSION
************************************************************/

function templateTextToAirtableHtml(value) {
    let s = String(value ?? "")
        .replace(/\r\n/g, "\n")
        .replace(/\\n/g, "\n");

    s = s.replace(/^###\s+(.*)$/gm, '<span style="font-size:16px;"><strong>$1</strong></span>');
    s = s.replace(/^##\s+(.*)$/gm, '<span style="font-size:18px;"><strong>$1</strong></span>');
    s = s.replace(/^#\s+(.*)$/gm, '<span style="font-size:20px;"><strong>$1</strong></span>');

    s = s.replace(/\*\*(.*?)\*\*/g, "<strong>$1</strong>");

    s = s.replace(/\[([^\]]+)\]\(\{?(https?:\/\/[^)\s}]+)\}?\)/g, '<a href="$2">$1</a>');

    s = s.replace(/\n/g, "<br>");

    return s;
}

function fieldTextToAirtableHtml(value) {
    let s = String(value ?? "")
        .replace(/\\n/g, "\n")
        .replace(/\r\n/g, "\n");

    s = htmlEscape(s);

    s = s.replace(/^###\s+(.*)$/gm, '<span style="font-size:16px;"><strong>$1</strong></span>');
    s = s.replace(/^##\s+(.*)$/gm, '<span style="font-size:18px;"><strong>$1</strong></span>');
    s = s.replace(/^#\s+(.*)$/gm, '<span style="font-size:20px;"><strong>$1</strong></span>');
    s = s.replace(/\*\*(.*?)\*\*/g, "<strong>$1</strong>");
    s = s.replace(/\n/g, "<br>");

    return s;
}

/************************************************************
JSON REPAIR + PARSING
************************************************************/

function escapeRawControlCharsInsideJsonStrings(input) {
    const s = String(input ?? "");
    let out = "";
    let inString = false;
    let escaped = false;

    for (let i = 0; i < s.length; i++) {
        const ch = s[i];

        if (escaped) {
            out += ch;
            escaped = false;
            continue;
        }

        if (ch === "\\") {
            out += ch;
            escaped = true;
            continue;
        }

        if (ch === '"') {
            inString = !inString;
            out += ch;
            continue;
        }

        if (inString) {
            if (ch === "\n") {
                out += "\\n";
                continue;
            }

            if (ch === "\r") {
                out += "\\r";
                continue;
            }

            if (ch === "\t") {
                out += "\\t";
                continue;
            }

            const code = ch.charCodeAt(0);
            if (code >= 0 && code <= 31) {
                out += "\\u" + code.toString(16).padStart(4, "0");
                continue;
            }
        }

        out += ch;
    }

    return out;
}

function parseReportItems(raw) {
    if (Array.isArray(raw)) {
        const cleanedArray = raw
            .map(v => {
                if (typeof v === "object" && v !== null) return v;
                return String(v ?? "").trim();
            })
            .filter(Boolean);

        if (!cleanedArray.length) return [];

        if (typeof cleanedArray[0] === "object") return cleanedArray;

        return parseReportItems(cleanedArray.join(","));
    }

    let clean = String(raw ?? "").trim();

    if (!clean) return [];

    clean = escapeRawControlCharsInsideJsonStrings(clean);

    try {
        if (clean.startsWith("[") && clean.endsWith("]")) {
            return JSON.parse(clean);
        }

        if (clean.startsWith("{") && clean.endsWith("}")) {
            return JSON.parse(`[${clean}]`);
        }

        return JSON.parse(`[${clean}]`);

    } catch (err) {
        throw new Error(
            [
                "Could not parse reportItemsJSON.",
                "",
                "Most likely causes:",
                "1. A double quote in an Airtable formula output was not escaped.",
                "2. Your rollup is not joining JSON objects with commas.",
                "3. A field contains malformed markdown/link syntax.",
                "",
                `Parse error: ${err.message}`,
                "",
                "Raw input starts with:",
                String(raw ?? "").slice(0, 1000),
                "",
                "Sanitized input starts with:",
                clean.slice(0, 1000)
            ].join("\n")
        );
    }
}

/************************************************************
CLAIMS
************************************************************/

function parseClaims(value) {
    if (Array.isArray(value)) {
        return value
            .map(v => String(v ?? "").trim())
            .filter(Boolean);
    }

    const s = normalizeText(value);
    if (!s) return [];

    let parts = s.split(/\n+/).map(v => v.trim()).filter(Boolean);

    if (parts.length === 1 && parts[0].match(/\(\d{1,2}\/\d{1,2}\/\d{4}\)/g)?.length > 1) {
        parts = parts[0]
            .split(/,\s*(?=\(\d{1,2}\/\d{1,2}\/\d{4}\)\s*\|)/)
            .map(v => v.trim())
            .filter(Boolean);
    }

    return parts;
}

/************************************************************
ITEM NORMALIZATION
************************************************************/

function prepareItem(item) {
    const rawEligible =
        item.eligibleProgramsRaw ??
        item.eligiblePrograms ??
        item["💛✅Eligible for Programs"] ??
        "";

    const rawIneligible =
        item.ineligibleProgramsRaw ??
        item.ineligiblePrograms ??
        item["💛❌Ineligible for Programs"] ??
        "";

    const rawCategories =
        item.triageCategoriesRaw ??
        item.triageCategories ??
        item["❗Triage 🛠️Request Categories"] ??
        "";

    let eligiblePrograms = [];

    if (Array.isArray(rawEligible)) {
        eligiblePrograms = rawEligible.map(cleanProgramName).filter(Boolean);
    } else {
        eligiblePrograms = splitLines(rawEligible).length
            ? splitLines(rawEligible).map(cleanProgramName).filter(Boolean)
            : splitCsvish(rawEligible).map(cleanProgramName).filter(Boolean);
    }

    let ineligiblePrograms = [];

    if (Array.isArray(rawIneligible)) {
        ineligiblePrograms = rawIneligible.map(cleanProgramName).filter(Boolean);
    } else {
        ineligiblePrograms = splitLines(rawIneligible).length
            ? splitLines(rawIneligible).map(cleanProgramName).filter(Boolean)
            : splitCsvish(rawIneligible).map(cleanProgramName).filter(Boolean);
    }

    const triageCategories = Array.isArray(rawCategories)
        ? rawCategories.map(v => String(v ?? "").trim()).filter(Boolean)
        : splitCsvish(rawCategories);

    const claimsRaw =
        item.claimsRaw ??
        item.claims ??
        item["🪝Claims"] ??
        item["Claims"] ??
        "";

    const propertyCardRaw =
        item.propertyCardRaw ??
        item.propertyCard ??
        item["Property Card "] ??
        item["Property Card"] ??
        "";

    const reviewRaw =
        item.reviewRaw ??
        item.reviewUrl ??
        item["📨Review Button"] ??
        "";

    return {
        id: item.id ?? item.recordId ?? "",
        oneLine: item.oneLine ?? item["✅Report"] ?? "",
        applicant: item.applicant ?? item["👤Applicant Full Name"] ?? "",
        address: item.address ?? item["📍Address"] ?? "",
        unit: item.unit ?? item["📍Unit"] ?? "",
        cityCheck: item.cityCheck ?? item["📍City of Asheville"] ?? "",
        neighborhood: item.neighborhood ?? item["📍Neighborhood"] ?? "",
        placeCode: item.placeCode ?? item["⚓📍PlaceCode"] ?? "",
        label: item.label ?? item["⚓🎯 Label"] ?? "",
        ami: item.ami ?? item["👤AMI%"] ?? "",
        submitted: item.submitted ?? item["📅Submission Date"] ?? "",
        submissionAge: item.submissionAge ?? item["🕰️Submission Age"] ?? "",

        eligiblePrograms,
        ineligiblePrograms,

        triageScore:
            item.triageScore ??
            item["❗Triage Score"] ??
            "",

        triageMessage:
            item.triageMessage ??
            item["❗Triage Message"] ??
            "",

        triageDemo:
            item.triageDemo ??
            item["❗Triage Demo"] ??
            "",

        triageCategories,

        triageWait:
            item.triageWait ??
            item["❗Triage 🕰️Wait time"] ??
            "",

        claims: parseClaims(claimsRaw),

        propertyCardRaw,
        reviewRaw,

        propertyCardUrl:
            item.propertyCardUrl ||
            extractUrl(propertyCardRaw),

        reviewUrl:
            item.reviewUrl ||
            extractUrl(reviewRaw)
    };
}

/************************************************************
EMAIL SECTION RENDERERS — AIRTABLE SAFE HTML
************************************************************/

function renderTopLineList(items) {
    if (!items.length) {
        return "<em>No matching reports found.</em><br>";
    }

    return items.map((item, i) => {
        const label = item.oneLine || `${item.applicant || "Unnamed applicant"} — ${item.address || ""}`;
        const review = item.reviewUrl
            ? ` <a href="${attrEscape(item.reviewUrl)}">Review</a>`
            : "";

        return `${i + 1}. ${htmlEscape(label)}${review}`;
    }).join("<br>");
}

function renderDetailCard(item, index) {
    const eligible = item.eligiblePrograms?.length
        ? item.eligiblePrograms.map(p => `✅ ${htmlEscape(p)}`).join("<br>")
        : "<em>None listed</em>";

    const ineligible = item.ineligiblePrograms?.length
        ? "<br><br><strong>Ineligible programs</strong><br>" +
          item.ineligiblePrograms.map(p => `❌ ${htmlEscape(p)}`).join("<br>")
        : "";

    const categories = item.triageCategories?.length
        ? item.triageCategories.map(c => htmlEscape(c)).join(", ")
        : "None listed";

    const claimsHtml = item.claims?.length
        ? "<br><br><strong>Claim status</strong><br>" +
          item.claims.map(c => `🪝 ${htmlEscape(c)}`).join("<br>")
        : "";

    const triageMessageHtml = item.triageMessage
        ? `<br><br><strong>Triage calculation</strong><br>${fieldTextToAirtableHtml(item.triageMessage)}`
        : "";

    const reviewLink = item.reviewUrl
        ? `<a href="${attrEscape(item.reviewUrl)}">Open Review Page</a>`
        : "";

    const propCardLink = item.propertyCardUrl
        ? `<a href="${attrEscape(item.propertyCardUrl)}">Property Card</a>`
        : "";

    const links = [reviewLink, propCardLink].filter(Boolean).join(" | ");

    const addressLine = [
        item.address ? htmlEscape(item.address) : "",
        item.unit ? `Unit ${htmlEscape(item.unit)}` : ""
    ].filter(Boolean).join(", ");

    return [
        "<br>",
        `<span style="font-size:18px;"><strong>${index + 1}. ${htmlEscape(item.applicant || "Unnamed applicant")}</strong></span>`,
        "<br>",
        addressLine || "<em>No address listed</em>",
        item.placeCode ? `<br>PlaceCode: ${htmlEscape(item.placeCode)}` : "",
        item.label ? `<br>Label: ${htmlEscape(item.label)}` : "",
        "<br><br>",

        `<strong>Triage Score:</strong> ${htmlEscape(item.triageScore || "—")}`,
        "<br>",
        `<strong>Submitted:</strong> ${htmlEscape(formatSubmittedDate(item.submitted, item.submissionAge) || "—")}`,
        "<br>",
        `<strong>AMI:</strong> ${htmlEscape(item.ami || "—")}`,
        "<br>",
        `<strong>City Check:</strong> ${htmlEscape(item.cityCheck || "—")}`,
        "<br>",
        `<strong>Neighborhood:</strong> ${htmlEscape(item.neighborhood || "—")}`,
        "<br>",
        `<strong>Wait Factor:</strong> ${htmlEscape(item.triageWait || "—")}`,
        "<br><br>",

        "<strong>Eligible programs</strong>",
        "<br>",
        eligible,
        ineligible,

        "<br><br>",
        "<strong>Request / triage categories</strong>",
        "<br>",
        categories,

        claimsHtml,

        item.triageDemo
            ? `<br><br><strong>Demographic triage notes</strong><br>${htmlEscape(item.triageDemo)}`
            : "",

        triageMessageHtml,

        links ? `<br><br>${links}` : "",

        "<br><br>",
        '<span style="color:#999999;">────────────────────────</span>',
        "<br>"
    ].join("");
}

/************************************************************
MAIN
************************************************************/

let items = parseReportItems(reportItemsRaw).map(prepareItem);

// Highest triage score first.
// Remove this sort if you want Airtable linked-record order preserved.
items.sort((a, b) => Number(b.triageScore || 0) - Number(a.triageScore || 0));

const reportCount = items.length;
const reportCountLabel = `${reportCount} ${reportCount === 1 ? "Submission" : "Submissions"}`;

const topLineHtml = renderTopLineList(items);
const detailHtml = items.map(renderDetailCard).join("<br>");

const tokens = {
    reportCount: String(reportCount),
    reportCountLabel,
    reportName,
    reportOrg,
    reportStart,
    reportEnd,

    "✅reportRollup": topLineHtml,
    "✅longerApplicantSummary (from the CSV)": detailHtml,

    reportRollup: topLineHtml,
    longerApplicantSummary: detailHtml,
    applicantSummary: detailHtml
};

const subject = replaceTokens(subjectTemplate, {
    ...tokens,

    "✅reportRollup": "",
    "✅longerApplicantSummary (from the CSV)": "",
    reportRollup: "",
    longerApplicantSummary: "",
    applicantSummary: ""
})
    .replace(/\s+/g, " ")
    .trim();

const renderedHead = replaceTokens(headTemplate, tokens);
const renderedBody = replaceTokens(bodyTemplate, tokens);

const html = [
    templateTextToAirtableHtml(renderedHead),
    "<br><br>",
    templateTextToAirtableHtml(renderedBody)
].join("");

const text = stripHtmlToText(html);

output.set("subject", subject);
output.set("html", html);
output.set("text", text);
output.set("reportCount", reportCount);

output.set("debugFirstApplicant", items[0]?.applicant || "");
output.set("debugFirstReviewUrl", items[0]?.reviewUrl || "");
output.set("debugFirstTriageScore", items[0]?.triageScore || "");
output.set("debugFirstClaims", items[0]?.claims?.join(" | ") || "");

