/******************************************************
 * Org Eligibility Evaluator
 *
 * Input vars:
 *   orgProgJSON = one org + all linked program profiles
 *   subJSON     = one submission eligibility profile
 *
 * Output:
 *   one org-level result:
 *     - alertText
 *     - reportJSON
 *     - eligibleProgramRecordIds
 *     - ineligibleProgramRecordIds
 *     - checkedProgramRecordIds
 *     - hasEligibleProgram
 *     - failSummary
 *     - omissionSummary
 *
 * Policy:
 *   - Omitted program restriction = auto-pass
 *   - Missing submission value = auto-pass
 *   - Only explicit contradiction = fail
 ******************************************************/

const { orgProgJSON, subJSON } = input.config();

if (!orgProgJSON) throw new Error("Missing input: orgProgJSON");
if (!subJSON) throw new Error("Missing input: subJSON");

/* ---------------- Parse helpers ---------------- */

function parseJsonMaybe(value, label = "JSON") {
  if (value === null || value === undefined || value === "") return null;
  if (typeof value === "object") return value;

  const s = String(value).trim();
  if (!s || s.toLowerCase() === "null") return null;

  try {
    return JSON.parse(s);
  } catch (err) {
    throw new Error(
      `Could not parse ${label}: ${err.message}\n\nStarts with:\n${s.slice(0, 500)}`
    );
  }
}

function cleanNull(value) {
  if (value === null || value === undefined) return null;
  if (typeof value === "string" && value.trim().toLowerCase() === "null") return null;
  return value;
}

function arrayify(value) {
  value = cleanNull(value);
  if (value === null || value === undefined || value === "") return [];
  return Array.isArray(value) ? value : [value];
}

function toNumber(value) {
  if (value === null || value === undefined || value === "") return NaN;
  const n = Number(String(value).replace(/[,$%\s]/g, ""));
  return Number.isFinite(n) ? n : NaN;
}

function toBool(value) {
  if (value === null || value === undefined || value === "") return null;
  if (typeof value === "boolean") return value;

  const s = String(value).trim().toLowerCase();

  if (["true", "t", "yes", "y", "1", "checked"].includes(s)) return true;
  if (["false", "f", "no", "n", "0", "unchecked"].includes(s)) return false;

  return null;
}

function norm(value) {
  return String(value ?? "")
    .toLowerCase()
    .trim()
    .replace(/[’']/g, "")
    .replace(/&/g, " and ")
    .replace(/[^\p{L}\p{N}\s]+/gu, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function normPlace(scale, value) {
  let s = norm(value);
  const sc = norm(scale);

  if (sc === "state") {
    if (["north carolina", "n carolina", "nc"].includes(s)) return "nc";
  }

  if (sc === "county") {
    s = s.replace(/\bcounty\b/g, "").replace(/\s+/g, " ").trim();
  }

  if (sc === "city" || sc === "town") {
    s = s.replace(/^city of\s+/, "").replace(/^town of\s+/, "").trim();
  }

  return s;
}

function display(value) {
  if (Array.isArray(value)) return value.join(", ");
  if (value === null || value === undefined || value === "") return "(blank)";
  return String(value);
}

function uniq(arr) {
  return [...new Set((arr || []).filter(Boolean))];
}

/* ---------------- Normalize submission ---------------- */

function normalizeSub(rawSub) {
  const phase1 = rawSub.subPhase1?.serviceArea ?? {};
  const phase2 = arrayify(rawSub.subPhase2);
  const phase3 = rawSub.subPhase3?.ownershipCheck ?? {};
  const phase4 = cleanNull(rawSub.subPhase4) ?? {};

  const income = {};

  for (const item of phase2) {
    const check = item?.incomeCheck ?? item;
    const calc = String(check?.calc ?? "").trim().toUpperCase();
    const percent = toNumber(check?.percent);

    if (calc && Number.isFinite(percent)) {
      income[calc] = percent;
    }
  }

  const demoRaw = phase4.demoCheck ?? phase4.demoGroup ?? [];
  let demoCodes = [];

  if (Array.isArray(demoRaw)) {
    demoCodes = demoRaw.map(String).map(s => s.trim()).filter(Boolean);
  } else if (demoRaw && typeof demoRaw === "object") {
    demoCodes = Object.entries(demoRaw)
      .filter(([, value]) => toBool(value) === true)
      .map(([key]) => key);
  }

  return {
    subKEY: rawSub.subKEY,
    subRecordId: rawSub.subRecordId,

    serviceArea: {
      state: phase1.state ?? "",
      county: phase1.county ?? "",
      city: phase1.city ?? "",
    },

    income,

    ownership: {
      typeHome: phase3.typeHome ?? "",
      bldgValue: toNumber(phase3.bldgValue),
      primaryRes: toBool(phase3.primaryRes),
      ownHome: toBool(phase3.ownHome),
      ownLot: toBool(phase3.ownLot),
      minTime: toNumber(phase3.minTime),
    },

    demoCodes,
    demoSet: new Set(demoCodes),
  };
}

/* ---------------- Report helpers ---------------- */

function makePhase(label) {
  return {
    label,
    pass: true,
    status: "PASS",
    passed: [],
    failed: [],
    autoPassed: [],
    priority: [],
  };
}

function addPass(phase, message, detail = {}) {
  phase.passed.push({ message, ...detail });
}

function addFail(phase, check, message, detail = {}) {
  phase.pass = false;
  phase.status = "FAIL";
  phase.failed.push({ check, message, ...detail });
}

function addAuto(phase, message, detail = {}) {
  phase.autoPassed.push({ message, ...detail });
}

function addPriority(phase, message, detail = {}) {
  phase.priority.push({ message, ...detail });
}

function detailLine(item) {
  const parts = [item.message || item.check || "check"];

  if (item.actual !== undefined) parts.push(`actual: ${display(item.actual)}`);
  if (item.expected !== undefined) parts.push(`expected: ${display(item.expected)}`);
  if (item.allowed !== undefined) parts.push(`allowed: ${display(item.allowed)}`);
  if (item.required !== undefined) parts.push(`required: ${display(item.required)}`);
  if (item.hits !== undefined) parts.push(`hits: ${display(item.hits)}`);

  return parts.join(" | ");
}

function getFails(phases) {
  return phases.flatMap(phase =>
    phase.failed.map(fail => ({
      phase: phase.label,
      ...fail,
    }))
  );
}

function getAutos(phases) {
  return phases.flatMap(phase =>
    phase.autoPassed.map(auto => ({
      phase: phase.label,
      ...auto,
    }))
  );
}

function getPriorityItems(phases) {
  return phases.flatMap(phase =>
    phase.priority.map(priority => ({
      phase: phase.label,
      ...priority,
    }))
  );
}

/* ---------------- Phase 1: service area ---------------- */

function normalizeServiceArea(program) {
  const raw = cleanNull(program.phase1);
  const items = arrayify(raw?.serviceArea ?? []);

  const byScale = {};

  for (const item of items) {
    const scale = norm(item.scale);
    const specific = item.specific;

    if (!scale || specific === undefined || specific === null || specific === "") continue;

    if (!byScale[scale]) byScale[scale] = [];
    byScale[scale].push(normPlace(scale, specific));
  }

  for (const key of Object.keys(byScale)) {
    byScale[key] = uniq(byScale[key]);
  }

  return byScale;
}

function checkServiceArea(sub, program) {
  const phase = makePhase("📍 Location");
  const allowed = normalizeServiceArea(program);

  function checkScale(scale, subValue, label) {
    const allowedValues = allowed[scale] || [];

    if (!allowedValues.length) {
      addAuto(phase, `Program omitted ${label} restriction.`);
      return;
    }

    if (!subValue) {
      addAuto(phase, `Submission missing ${label}; auto-pass by omission policy.`, {
        allowed: allowedValues,
      });
      return;
    }

    const actual = normPlace(scale, subValue);

    if (allowedValues.includes(actual)) {
      addPass(phase, `${label} matched ${subValue}.`, {
        actual: subValue,
        allowed: allowedValues,
      });
    } else {
      addFail(phase, label, `${label} did not match allowed service area.`, {
        actual: subValue,
        allowed: allowedValues,
      });
    }
  }

  checkScale("state", sub.serviceArea.state, "state");
  checkScale("county", sub.serviceArea.county, "county");
  checkScale("city", sub.serviceArea.city, "city");

  return phase;
}

/* ---------------- Phase 2: income ---------------- */

function normalizeIncomeRules(program) {
  const raw = cleanNull(program.phase2);
  const check = raw?.incomeCheck ?? raw?.incomeChecks ?? raw;

  if (!check) return [];

  return arrayify(check)
    .map(item => item?.incomeCheck ?? item)
    .map(item => ({
      calc: String(item?.calc ?? "").trim().toUpperCase(),
      max: toNumber(item?.max),
    }))
    .filter(item => item.calc && Number.isFinite(item.max));
}

function checkIncome(sub, program) {
  const phase = makePhase("💲 Income");
  const rules = normalizeIncomeRules(program);

  if (!rules.length) {
    addAuto(phase, "Program omitted income restriction.");
    return phase;
  }

  let hasPass = false;
  let hasMissingAutoPass = false;
  const explicitFails = [];

  for (const rule of rules) {
    const actual = sub.income[rule.calc];

    if (!Number.isFinite(actual)) {
      hasMissingAutoPass = true;
      addAuto(phase, `Submission missing ${rule.calc}% value; auto-pass by omission policy.`, {
        expected: `<= ${rule.max}%`,
      });
      continue;
    }

    if (actual <= rule.max) {
      hasPass = true;
      addPass(phase, `${rule.calc} ${actual}% is at/below max ${rule.max}%.`, {
        actual: `${actual}%`,
        expected: `<= ${rule.max}%`,
      });
    } else {
      explicitFails.push({
        calc: rule.calc,
        actual,
        max: rule.max,
      });
    }
  }

  // Any matching income basis passes the income phase.
  // Only fail if every available basis explicitly fails.
  if (hasPass || hasMissingAutoPass) return phase;

  for (const fail of explicitFails) {
    addFail(phase, `income:${fail.calc}`, `${fail.calc} ${fail.actual}% is above max ${fail.max}%.`, {
      actual: `${fail.actual}%`,
      expected: `<= ${fail.max}%`,
    });
  }

  return phase;
}

/* ---------------- Phase 3: ownership ---------------- */

function normalizeOwnershipRules(program) {
  const raw = cleanNull(program.phase3);

  const checks =
    raw?.ownershipChecks ??
    raw?.ownershipCheck ??
    [];

  return arrayify(checks)
    .map(item => item?.ownershipCheck ?? item)
    .filter(item => item && typeof item === "object");
}

function evaluateOwnershipProfile(sub, rule, index) {
  const result = {
    index,
    pass: true,
    passed: [],
    failed: [],
    autoPassed: [],
  };

  function rPass(message, detail = {}) {
    result.passed.push({ message, ...detail });
  }

  function rFail(check, message, detail = {}) {
    result.pass = false;
    result.failed.push({ check, message, ...detail });
  }

  function rAuto(message, detail = {}) {
    result.autoPassed.push({ message, ...detail });
  }

  if (Array.isArray(rule.typeHome) && rule.typeHome.length) {
    const actual = sub.ownership.typeHome;

    if (!actual) {
      rAuto("Submission missing home type; auto-pass by omission policy.", {
        allowed: rule.typeHome,
      });
    } else {
      const allowed = rule.typeHome.map(norm);

      if (allowed.includes(norm(actual))) {
        rPass(`Home type ${actual} is allowed.`, {
          actual,
          allowed: rule.typeHome,
        });
      } else {
        rFail("typeHome", `Home type ${actual} is not allowed.`, {
          actual,
          allowed: rule.typeHome,
        });
      }
    }
  } else {
    rAuto("Program omitted home type restriction.");
  }

  if (rule.bldgValue !== undefined && rule.bldgValue !== null && rule.bldgValue !== "") {
    const max = toNumber(rule.bldgValue);
    const actual = sub.ownership.bldgValue;

    if (!Number.isFinite(actual)) {
      rAuto("Submission missing building value; auto-pass by omission policy.", {
        expected: `<= ${max}`,
      });
    } else if (Number.isFinite(max) && actual <= max) {
      rPass(`Building value ${actual} is at/below max ${max}.`, {
        actual,
        expected: `<= ${max}`,
      });
    } else if (Number.isFinite(max)) {
      rFail("bldgValue", `Building value ${actual} is above max ${max}.`, {
        actual,
        expected: `<= ${max}`,
      });
    }
  } else {
    rAuto("Program omitted building value restriction.");
  }

  for (const key of ["primaryRes", "ownHome", "ownLot"]) {
    const expected = toBool(rule[key]);

    if (expected === null) {
      rAuto(`Program omitted ${key} restriction.`);
      continue;
    }

    const actual = sub.ownership[key];

    if (actual === null) {
      rAuto(`Submission missing ${key}; auto-pass by omission policy.`, {
        expected,
      });
    } else if (actual === expected) {
      rPass(`${key} matched ${expected}.`, {
        actual,
        expected,
      });
    } else {
      rFail(key, `${key} did not match required value.`, {
        actual,
        expected,
      });
    }
  }

  if (rule.minTime !== undefined && rule.minTime !== null && rule.minTime !== "") {
    const min = toNumber(rule.minTime);
    const actual = sub.ownership.minTime;

    if (!Number.isFinite(actual)) {
      rAuto("Submission missing ownership duration; auto-pass by omission policy.", {
        expected: `>= ${min} months`,
      });
    } else if (Number.isFinite(min) && actual >= min) {
      rPass(`Ownership duration ${actual} months is at/above required ${min} months.`, {
        actual: `${actual} months`,
        expected: `>= ${min} months`,
      });
    } else if (Number.isFinite(min)) {
      rFail("minTime", `Ownership duration ${actual} months is below required ${min} months.`, {
        actual: `${actual} months`,
        expected: `>= ${min} months`,
      });
    }
  } else {
    rAuto("Program omitted ownership duration restriction.");
  }

  return result;
}

function checkOwnership(sub, program) {
  const phase = makePhase("🏡 Ownership");
  const rules = normalizeOwnershipRules(program);

  if (!rules.length) {
    addAuto(phase, "Program omitted ownership restrictions.");
    return phase;
  }

  const profiles = rules.map((rule, index) =>
    evaluateOwnershipProfile(sub, rule, index + 1)
  );

  const passingProfile = profiles.find(profile => profile.pass);

  if (passingProfile) {
    addPass(phase, `Ownership profile ${passingProfile.index} matched.`);

    phase.passed.push(...passingProfile.passed);
    phase.autoPassed.push(...passingProfile.autoPassed);

    return phase;
  }

  const failMessages = profiles.flatMap(profile =>
    profile.failed.map(fail => `Profile ${profile.index}: ${detailLine(fail)}`)
  );

  addFail(phase, "ownershipProfile", `No ownership profile matched. ${failMessages.join(" ")}`, {
    profiles,
  });

  return phase;
}

/* ---------------- Phase 4: demo ---------------- */

function normalizeDemoRule(program) {
  const raw = cleanNull(program.phase4);
  if (!raw) return null;

  const qual = String(raw.demoQual ?? raw.qual ?? "").trim();
  const group = raw.demoGroup ?? raw.demoCheck ?? {};

  let codes = [];

  if (Array.isArray(group)) {
    codes = group.map(String).map(s => s.trim()).filter(Boolean);
  } else if (group && typeof group === "object") {
    codes = Object.entries(group)
      .filter(([, value]) => toBool(value) === true)
      .map(([key]) => key);
  }

  if (!qual && !codes.length) return null;

  return {
    qual,
    codes,
  };
}

function checkDemo(sub, program) {
  const phase = makePhase("👤 Demographics");
  const rule = normalizeDemoRule(program);

  if (!rule || !rule.codes.length) {
    addAuto(phase, "Program omitted demographic restriction.");
    return phase;
  }

  const qual = norm(rule.qual);
  const hits = rule.codes.filter(code => sub.demoSet.has(code));

  if (qual === "required") {
    if (!sub.demoCodes.length) {
      addAuto(phase, "Submission missing demographic flags; auto-pass by omission policy.", {
        required: rule.codes,
      });
      return phase;
    }

    if (hits.length > 0) {
      addPass(phase, `Required demographic matched ${hits.join(", ")}.`, {
        required: rule.codes,
        hits,
      });
    } else {
      addFail(phase, "demoRequired", "Required demographic did not match.", {
        required: rule.codes,
        hits,
      });
    }

    return phase;
  }

  if (qual === "prioritized") {
    if (hits.length > 0) {
      addPriority(phase, `Prioritized demographic matched ${hits.join(", ")}.`, {
        hits,
        priorityHit: true,
      });
    } else {
      addPriority(phase, "No prioritized demographic match; not disqualifying.", {
        required: rule.codes,
        hits,
        priorityHit: false,
      });
    }

    return phase;
  }

  addAuto(phase, `Demographic rule type "${rule.qual}" is not blocking; treated as non-disqualifying.`, {
    rule,
    hits,
  });

  return phase;
}

/* ---------------- Program evaluator ---------------- */

function shortFailReason(programResult) {
  if (!programResult.failReasons.length) return "";

  const first = programResult.failReasons[0];

  let msg = first.message || "Failed eligibility check.";

  // Strip a little noise for email/report display.
  msg = msg
    .replace(/^No ownership profile matched\.\s*/i, "")
    .trim();

  if (!msg) msg = first.check || "Failed eligibility check.";

  return msg;
}

function evaluateProgram(sub, program) {
  const phases = [
    checkServiceArea(sub, program),
    checkIncome(sub, program),
    checkOwnership(sub, program),
    checkDemo(sub, program),
  ];

  const failReasons = getFails(phases);
  const autoPasses = getAutos(phases);
  const priorityItems = getPriorityItems(phases);

  const eligible = failReasons.length === 0;
  const priorityHit = priorityItems.some(item => item.priorityHit === true);

  const programName = program.programName || program.name || program.progRecordId || program.programKEY || "Unnamed Program";

  const summary = eligible
    ? `${programName} ✅`
    : `${programName} ❌ — ${shortFailReason({ failReasons })}`;

  return {
    programKEY: program.programKEY ?? null,
    programName,
    progRecordId: program.progRecordId ?? null,

    eligible,
    priorityHit,

    summary,
    failReasons,
    autoPasses,
    priorityItems,
    phases,
  };
}

/* ---------------- Org-level aggregation ---------------- */

function buildAlertText(programResults) {
  return programResults.map(result => result.summary).join("\n");
}

function buildFailSummary(programResults) {
  const lines = [];

  for (const result of programResults) {
    if (!result.failReasons.length) continue;

    lines.push(`${result.programName}:`);
    for (const fail of result.failReasons) {
      lines.push(`- ${fail.phase}: ${detailLine(fail)}`);
    }
  }

  return lines.length ? lines.join("\n") : "";
}

function buildOmissionSummary(programResults) {
  const lines = [];

  for (const result of programResults) {
    if (!result.autoPasses.length) continue;

    lines.push(`${result.programName}:`);
    for (const auto of result.autoPasses) {
      lines.push(`- ${auto.phase}: ${detailLine(auto)}`);
    }
  }

  return lines.length ? lines.join("\n") : "";
}

/* ---------------- MAIN ---------------- */

const org = parseJsonMaybe(orgProgJSON, "orgProgJSON");
const subRaw = parseJsonMaybe(subJSON, "subJSON");

if (!org || typeof org !== "object") throw new Error("orgProgJSON did not parse to an object.");
if (!subRaw || typeof subRaw !== "object") throw new Error("subJSON did not parse to an object.");

const sub = normalizeSub(subRaw);
const programs = arrayify(org.programs);

const programResults = programs.map(program => evaluateProgram(sub, program));

const eligibleProgramRecordIds = uniq(
  programResults
    .filter(result => result.eligible)
    .map(result => result.progRecordId)
);

const ineligibleProgramRecordIds = uniq(
  programResults
    .filter(result => !result.eligible)
    .map(result => result.progRecordId)
);

const checkedProgramRecordIds = uniq(
  programResults.map(result => result.progRecordId)
);

const eligibleProgramKeys = uniq(
  programResults
    .filter(result => result.eligible)
    .map(result => result.programKEY)
);

const ineligibleProgramKeys = uniq(
  programResults
    .filter(result => !result.eligible)
    .map(result => result.programKEY)
);

const checkedProgramKeys = uniq(
  programResults.map(result => result.programKEY)
);

const hasEligibleProgram = eligibleProgramRecordIds.length > 0;

const alertText = buildAlertText(programResults);
const failSummary = buildFailSummary(programResults);
const omissionSummary = buildOmissionSummary(programResults);

const report = {
  schema: "orgEligibilityReport.v1",
  generatedAt: new Date().toISOString(),

  orgKey: org.orgKey ?? null,
  orgRecordId: org.orgRecordId ?? null,

  subKEY: sub.subKEY ?? null,
  subRecordId: sub.subRecordId ?? null,

  hasEligibleProgram,

  eligibleProgramRecordIds,
  ineligibleProgramRecordIds,
  checkedProgramRecordIds,

  eligibleProgramKeys,
  ineligibleProgramKeys,
  checkedProgramKeys,

  alertText,
  failSummary,
  omissionSummary,

  programResults,
};

/* ---------------- Outputs ---------------- */

const eligibleProgramLinks = eligibleProgramRecordIds.map(id => ({ id }));
const ineligibleProgramLinks = ineligibleProgramRecordIds.map(id => ({ id }));
const checkedProgramLinks = checkedProgramRecordIds.map(id => ({ id }));

output.set("hasEligibleProgram", hasEligibleProgram);

output.set("alertText", alertText);
output.set("failSummary", failSummary);
output.set("omissionSummary", omissionSummary);

output.set("reportJSON", JSON.stringify(report, null, 2));

output.set("eligibleProgramRecordIds", eligibleProgramRecordIds);
output.set("ineligibleProgramRecordIds", ineligibleProgramRecordIds);
output.set("checkedProgramRecordIds", checkedProgramRecordIds);

output.set("eligibleProgramLinks", eligibleProgramLinks);
output.set("ineligibleProgramLinks", ineligibleProgramLinks);
output.set("checkedProgramLinks", checkedProgramLinks);

output.set("eligibleProgramKeys", eligibleProgramKeys);
output.set("ineligibleProgramKeys", ineligibleProgramKeys);
output.set("checkedProgramKeys", checkedProgramKeys);

output.set("orgRecordId", org.orgRecordId || "");
output.set("orgKey", org.orgKey || "");

output.set("subRecordId", sub.subRecordId || "");
output.set("subKEY", sub.subKEY || "");

script:
/******************************************************
 * Org Eligibility Evaluator
 *
 * Input vars:
 *   orgProgJSON = one org + all linked program profiles
 *   subJSON     = one submission eligibility profile
 *
 * Output:
 *   one org-level result:
 *     - alertText
 *     - reportJSON
 *     - eligibleProgramRecordIds
 *     - ineligibleProgramRecordIds
 *     - checkedProgramRecordIds
 *     - hasEligibleProgram
 *     - failSummary
 *     - omissionSummary
 *
 * Policy:
 *   - Omitted program restriction = auto-pass
 *   - Missing submission value = auto-pass
 *   - Only explicit contradiction = fail
 ******************************************************/

const { orgProgJSON, subJSON } = input.config();

if (!orgProgJSON) throw new Error("Missing input: orgProgJSON");
if (!subJSON) throw new Error("Missing input: subJSON");

/* ---------------- Parse helpers ---------------- */

function parseJsonMaybe(value, label = "JSON") {
  if (value === null || value === undefined || value === "") return null;
  if (typeof value === "object") return value;

  const s = String(value).trim();
  if (!s || s.toLowerCase() === "null") return null;

  try {
    return JSON.parse(s);
  } catch (err) {
    throw new Error(
      `Could not parse ${label}: ${err.message}\n\nStarts with:\n${s.slice(0, 500)}`
    );
  }
}

function cleanNull(value) {
  if (value === null || value === undefined) return null;
  if (typeof value === "string" && value.trim().toLowerCase() === "null") return null;
  return value;
}

function arrayify(value) {
  value = cleanNull(value);
  if (value === null || value === undefined || value === "") return [];
  return Array.isArray(value) ? value : [value];
}

function toNumber(value) {
  if (value === null || value === undefined || value === "") return NaN;
  const n = Number(String(value).replace(/[,$%\s]/g, ""));
  return Number.isFinite(n) ? n : NaN;
}

function toBool(value) {
  if (value === null || value === undefined || value === "") return null;
  if (typeof value === "boolean") return value;

  const s = String(value).trim().toLowerCase();

  if (["true", "t", "yes", "y", "1", "checked"].includes(s)) return true;
  if (["false", "f", "no", "n", "0", "unchecked"].includes(s)) return false;

  return null;
}

function norm(value) {
  return String(value ?? "")
    .toLowerCase()
    .trim()
    .replace(/[’']/g, "")
    .replace(/&/g, " and ")
    .replace(/[^\p{L}\p{N}\s]+/gu, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function normPlace(scale, value) {
  let s = norm(value);
  const sc = norm(scale);

  if (sc === "state") {
    if (["north carolina", "n carolina", "nc"].includes(s)) return "nc";
  }

  if (sc === "county") {
    s = s.replace(/\bcounty\b/g, "").replace(/\s+/g, " ").trim();
  }

  if (sc === "city" || sc === "town") {
    s = s.replace(/^city of\s+/, "").replace(/^town of\s+/, "").trim();
  }

  return s;
}

function display(value) {
  if (Array.isArray(value)) return value.join(", ");
  if (value === null || value === undefined || value === "") return "(blank)";
  return String(value);
}

function uniq(arr) {
  return [...new Set((arr || []).filter(Boolean))];
}

/* ---------------- Normalize submission ---------------- */

function normalizeSub(rawSub) {
  const phase1 = rawSub.subPhase1?.serviceArea ?? {};
  const phase2 = arrayify(rawSub.subPhase2);
  const phase3 = rawSub.subPhase3?.ownershipCheck ?? {};
  const phase4 = cleanNull(rawSub.subPhase4) ?? {};

  const income = {};

  for (const item of phase2) {
    const check = item?.incomeCheck ?? item;
    const calc = String(check?.calc ?? "").trim().toUpperCase();
    const percent = toNumber(check?.percent);

    if (calc && Number.isFinite(percent)) {
      income[calc] = percent;
    }
  }

  const demoRaw = phase4.demoCheck ?? phase4.demoGroup ?? [];
  let demoCodes = [];

  if (Array.isArray(demoRaw)) {
    demoCodes = demoRaw.map(String).map(s => s.trim()).filter(Boolean);
  } else if (demoRaw && typeof demoRaw === "object") {
    demoCodes = Object.entries(demoRaw)
      .filter(([, value]) => toBool(value) === true)
      .map(([key]) => key);
  }

  return {
    subKEY: rawSub.subKEY,
    subRecordId: rawSub.subRecordId,

    serviceArea: {
      state: phase1.state ?? "",
      county: phase1.county ?? "",
      city: phase1.city ?? "",
    },

    income,

    ownership: {
      typeHome: phase3.typeHome ?? "",
      bldgValue: toNumber(phase3.bldgValue),
      primaryRes: toBool(phase3.primaryRes),
      ownHome: toBool(phase3.ownHome),
      ownLot: toBool(phase3.ownLot),
      minTime: toNumber(phase3.minTime),
    },

    demoCodes,
    demoSet: new Set(demoCodes),
  };
}

/* ---------------- Report helpers ---------------- */

function makePhase(label) {
  return {
    label,
    pass: true,
    status: "PASS",
    passed: [],
    failed: [],
    autoPassed: [],
    priority: [],
  };
}

function addPass(phase, message, detail = {}) {
  phase.passed.push({ message, ...detail });
}

function addFail(phase, check, message, detail = {}) {
  phase.pass = false;
  phase.status = "FAIL";
  phase.failed.push({ check, message, ...detail });
}

function addAuto(phase, message, detail = {}) {
  phase.autoPassed.push({ message, ...detail });
}

function addPriority(phase, message, detail = {}) {
  phase.priority.push({ message, ...detail });
}

function detailLine(item) {
  const parts = [item.message || item.check || "check"];

  if (item.actual !== undefined) parts.push(`actual: ${display(item.actual)}`);
  if (item.expected !== undefined) parts.push(`expected: ${display(item.expected)}`);
  if (item.allowed !== undefined) parts.push(`allowed: ${display(item.allowed)}`);
  if (item.required !== undefined) parts.push(`required: ${display(item.required)}`);
  if (item.hits !== undefined) parts.push(`hits: ${display(item.hits)}`);

  return parts.join(" | ");
}

function getFails(phases) {
  return phases.flatMap(phase =>
    phase.failed.map(fail => ({
      phase: phase.label,
      ...fail,
    }))
  );
}

function getAutos(phases) {
  return phases.flatMap(phase =>
    phase.autoPassed.map(auto => ({
      phase: phase.label,
      ...auto,
    }))
  );
}

function getPriorityItems(phases) {
  return phases.flatMap(phase =>
    phase.priority.map(priority => ({
      phase: phase.label,
      ...priority,
    }))
  );
}

/* ---------------- Phase 1: service area ---------------- */

function normalizeServiceArea(program) {
  const raw = cleanNull(program.phase1);
  const items = arrayify(raw?.serviceArea ?? []);

  const byScale = {};

  for (const item of items) {
    const scale = norm(item.scale);
    const specific = item.specific;

    if (!scale || specific === undefined || specific === null || specific === "") continue;

    if (!byScale[scale]) byScale[scale] = [];
    byScale[scale].push(normPlace(scale, specific));
  }

  for (const key of Object.keys(byScale)) {
    byScale[key] = uniq(byScale[key]);
  }

  return byScale;
}

function checkServiceArea(sub, program) {
  const phase = makePhase("📍 Location");
  const allowed = normalizeServiceArea(program);

  function checkScale(scale, subValue, label) {
    const allowedValues = allowed[scale] || [];

    if (!allowedValues.length) {
      addAuto(phase, `Program omitted ${label} restriction.`);
      return;
    }

    if (!subValue) {
      addAuto(phase, `Submission missing ${label}; auto-pass by omission policy.`, {
        allowed: allowedValues,
      });
      return;
    }

    const actual = normPlace(scale, subValue);

    if (allowedValues.includes(actual)) {
      addPass(phase, `${label} matched ${subValue}.`, {
        actual: subValue,
        allowed: allowedValues,
      });
    } else {
      addFail(phase, label, `${label} did not match allowed service area.`, {
        actual: subValue,
        allowed: allowedValues,
      });
    }
  }

  checkScale("state", sub.serviceArea.state, "state");
  checkScale("county", sub.serviceArea.county, "county");
  checkScale("city", sub.serviceArea.city, "city");

  return phase;
}

/* ---------------- Phase 2: income ---------------- */

function normalizeIncomeRules(program) {
  const raw = cleanNull(program.phase2);
  const check = raw?.incomeCheck ?? raw?.incomeChecks ?? raw;

  if (!check) return [];

  return arrayify(check)
    .map(item => item?.incomeCheck ?? item)
    .map(item => ({
      calc: String(item?.calc ?? "").trim().toUpperCase(),
      max: toNumber(item?.max),
    }))
    .filter(item => item.calc && Number.isFinite(item.max));
}

function checkIncome(sub, program) {
  const phase = makePhase("💲 Income");
  const rules = normalizeIncomeRules(program);

  if (!rules.length) {
    addAuto(phase, "Program omitted income restriction.");
    return phase;
  }

  let hasPass = false;
  let hasMissingAutoPass = false;
  const explicitFails = [];

  for (const rule of rules) {
    const actual = sub.income[rule.calc];

    if (!Number.isFinite(actual)) {
      hasMissingAutoPass = true;
      addAuto(phase, `Submission missing ${rule.calc}% value; auto-pass by omission policy.`, {
        expected: `<= ${rule.max}%`,
      });
      continue;
    }

    if (actual <= rule.max) {
      hasPass = true;
      addPass(phase, `${rule.calc} ${actual}% is at/below max ${rule.max}%.`, {
        actual: `${actual}%`,
        expected: `<= ${rule.max}%`,
      });
    } else {
      explicitFails.push({
        calc: rule.calc,
        actual,
        max: rule.max,
      });
    }
  }

  // Any matching income basis passes the income phase.
  // Only fail if every available basis explicitly fails.
  if (hasPass || hasMissingAutoPass) return phase;

  for (const fail of explicitFails) {
    addFail(phase, `income:${fail.calc}`, `${fail.calc} ${fail.actual}% is above max ${fail.max}%.`, {
      actual: `${fail.actual}%`,
      expected: `<= ${fail.max}%`,
    });
  }

  return phase;
}

/* ---------------- Phase 3: ownership ---------------- */

function normalizeOwnershipRules(program) {
  const raw = cleanNull(program.phase3);

  const checks =
    raw?.ownershipChecks ??
    raw?.ownershipCheck ??
    [];

  return arrayify(checks)
    .map(item => item?.ownershipCheck ?? item)
    .filter(item => item && typeof item === "object");
}

function evaluateOwnershipProfile(sub, rule, index) {
  const result = {
    index,
    pass: true,
    passed: [],
    failed: [],
    autoPassed: [],
  };

  function rPass(message, detail = {}) {
    result.passed.push({ message, ...detail });
  }

  function rFail(check, message, detail = {}) {
    result.pass = false;
    result.failed.push({ check, message, ...detail });
  }

  function rAuto(message, detail = {}) {
    result.autoPassed.push({ message, ...detail });
  }

  if (Array.isArray(rule.typeHome) && rule.typeHome.length) {
    const actual = sub.ownership.typeHome;

    if (!actual) {
      rAuto("Submission missing home type; auto-pass by omission policy.", {
        allowed: rule.typeHome,
      });
    } else {
      const allowed = rule.typeHome.map(norm);

      if (allowed.includes(norm(actual))) {
        rPass(`Home type ${actual} is allowed.`, {
          actual,
          allowed: rule.typeHome,
        });
      } else {
        rFail("typeHome", `Home type ${actual} is not allowed.`, {
          actual,
          allowed: rule.typeHome,
        });
      }
    }
  } else {
    rAuto("Program omitted home type restriction.");
  }

  if (rule.bldgValue !== undefined && rule.bldgValue !== null && rule.bldgValue !== "") {
    const max = toNumber(rule.bldgValue);
    const actual = sub.ownership.bldgValue;

    if (!Number.isFinite(actual)) {
      rAuto("Submission missing building value; auto-pass by omission policy.", {
        expected: `<= ${max}`,
      });
    } else if (Number.isFinite(max) && actual <= max) {
      rPass(`Building value ${actual} is at/below max ${max}.`, {
        actual,
        expected: `<= ${max}`,
      });
    } else if (Number.isFinite(max)) {
      rFail("bldgValue", `Building value ${actual} is above max ${max}.`, {
        actual,
        expected: `<= ${max}`,
      });
    }
  } else {
    rAuto("Program omitted building value restriction.");
  }

  for (const key of ["primaryRes", "ownHome", "ownLot"]) {
    const expected = toBool(rule[key]);

    if (expected === null) {
      rAuto(`Program omitted ${key} restriction.`);
      continue;
    }

    const actual = sub.ownership[key];

    if (actual === null) {
      rAuto(`Submission missing ${key}; auto-pass by omission policy.`, {
        expected,
      });
    } else if (actual === expected) {
      rPass(`${key} matched ${expected}.`, {
        actual,
        expected,
      });
    } else {
      rFail(key, `${key} did not match required value.`, {
        actual,
        expected,
      });
    }
  }

  if (rule.minTime !== undefined && rule.minTime !== null && rule.minTime !== "") {
    const min = toNumber(rule.minTime);
    const actual = sub.ownership.minTime;

    if (!Number.isFinite(actual)) {
      rAuto("Submission missing ownership duration; auto-pass by omission policy.", {
        expected: `>= ${min} months`,
      });
    } else if (Number.isFinite(min) && actual >= min) {
      rPass(`Ownership duration ${actual} months is at/above required ${min} months.`, {
        actual: `${actual} months`,
        expected: `>= ${min} months`,
      });
    } else if (Number.isFinite(min)) {
      rFail("minTime", `Ownership duration ${actual} months is below required ${min} months.`, {
        actual: `${actual} months`,
        expected: `>= ${min} months`,
      });
    }
  } else {
    rAuto("Program omitted ownership duration restriction.");
  }

  return result;
}

function checkOwnership(sub, program) {
  const phase = makePhase("🏡 Ownership");
  const rules = normalizeOwnershipRules(program);

  if (!rules.length) {
    addAuto(phase, "Program omitted ownership restrictions.");
    return phase;
  }

  const profiles = rules.map((rule, index) =>
    evaluateOwnershipProfile(sub, rule, index + 1)
  );

  const passingProfile = profiles.find(profile => profile.pass);

  if (passingProfile) {
    addPass(phase, `Ownership profile ${passingProfile.index} matched.`);

    phase.passed.push(...passingProfile.passed);
    phase.autoPassed.push(...passingProfile.autoPassed);

    return phase;
  }

  const failMessages = profiles.flatMap(profile =>
    profile.failed.map(fail => `Profile ${profile.index}: ${detailLine(fail)}`)
  );

  addFail(phase, "ownershipProfile", `No ownership profile matched. ${failMessages.join(" ")}`, {
    profiles,
  });

  return phase;
}

/* ---------------- Phase 4: demo ---------------- */

function normalizeDemoRule(program) {
  const raw = cleanNull(program.phase4);
  if (!raw) return null;

  const qual = String(raw.demoQual ?? raw.qual ?? "").trim();
  const group = raw.demoGroup ?? raw.demoCheck ?? {};

  let codes = [];

  if (Array.isArray(group)) {
    codes = group.map(String).map(s => s.trim()).filter(Boolean);
  } else if (group && typeof group === "object") {
    codes = Object.entries(group)
      .filter(([, value]) => toBool(value) === true)
      .map(([key]) => key);
  }

  if (!qual && !codes.length) return null;

  return {
    qual,
    codes,
  };
}

function checkDemo(sub, program) {
  const phase = makePhase("👤 Demographics");
  const rule = normalizeDemoRule(program);

  if (!rule || !rule.codes.length) {
    addAuto(phase, "Program omitted demographic restriction.");
    return phase;
  }

  const qual = norm(rule.qual);
  const hits = rule.codes.filter(code => sub.demoSet.has(code));

  if (qual === "required") {
    if (!sub.demoCodes.length) {
      addAuto(phase, "Submission missing demographic flags; auto-pass by omission policy.", {
        required: rule.codes,
      });
      return phase;
    }

    if (hits.length > 0) {
      addPass(phase, `Required demographic matched ${hits.join(", ")}.`, {
        required: rule.codes,
        hits,
      });
    } else {
      addFail(phase, "demoRequired", "Required demographic did not match.", {
        required: rule.codes,
        hits,
      });
    }

    return phase;
  }

  if (qual === "prioritized") {
    if (hits.length > 0) {
      addPriority(phase, `Prioritized demographic matched ${hits.join(", ")}.`, {
        hits,
        priorityHit: true,
      });
    } else {
      addPriority(phase, "No prioritized demographic match; not disqualifying.", {
        required: rule.codes,
        hits,
        priorityHit: false,
      });
    }

    return phase;
  }

  addAuto(phase, `Demographic rule type "${rule.qual}" is not blocking; treated as non-disqualifying.`, {
    rule,
    hits,
  });

  return phase;
}

/* ---------------- Program evaluator ---------------- */

function shortFailReason(programResult) {
  if (!programResult.failReasons.length) return "";

  const first = programResult.failReasons[0];

  let msg = first.message || "Failed eligibility check.";

  // Strip a little noise for email/report display.
  msg = msg
    .replace(/^No ownership profile matched\.\s*/i, "")
    .trim();

  if (!msg) msg = first.check || "Failed eligibility check.";

  return msg;
}

function evaluateProgram(sub, program) {
  const phases = [
    checkServiceArea(sub, program),
    checkIncome(sub, program),
    checkOwnership(sub, program),
    checkDemo(sub, program),
  ];

  const failReasons = getFails(phases);
  const autoPasses = getAutos(phases);
  const priorityItems = getPriorityItems(phases);

  const eligible = failReasons.length === 0;
  const priorityHit = priorityItems.some(item => item.priorityHit === true);

  const programName = program.programName || program.name || program.progRecordId || program.programKEY || "Unnamed Program";

  const summary = eligible
    ? `${programName} ✅`
    : `${programName} ❌ — ${shortFailReason({ failReasons })}`;

  return {
    programKEY: program.programKEY ?? null,
    programName,
    progRecordId: program.progRecordId ?? null,

    eligible,
    priorityHit,

    summary,
    failReasons,
    autoPasses,
    priorityItems,
    phases,
  };
}

/* ---------------- Org-level aggregation ---------------- */

function buildAlertText(programResults) {
  return programResults.map(result => result.summary).join("\n");
}

function buildFailSummary(programResults) {
  const lines = [];

  for (const result of programResults) {
    if (!result.failReasons.length) continue;

    lines.push(`${result.programName}:`);
    for (const fail of result.failReasons) {
      lines.push(`- ${fail.phase}: ${detailLine(fail)}`);
    }
  }

  return lines.length ? lines.join("\n") : "";
}

function buildOmissionSummary(programResults) {
  const lines = [];

  for (const result of programResults) {
    if (!result.autoPasses.length) continue;

    lines.push(`${result.programName}:`);
    for (const auto of result.autoPasses) {
      lines.push(`- ${auto.phase}: ${detailLine(auto)}`);
    }
  }

  return lines.length ? lines.join("\n") : "";
}

/* ---------------- MAIN ---------------- */

const org = parseJsonMaybe(orgProgJSON, "orgProgJSON");
const subRaw = parseJsonMaybe(subJSON, "subJSON");

if (!org || typeof org !== "object") throw new Error("orgProgJSON did not parse to an object.");
if (!subRaw || typeof subRaw !== "object") throw new Error("subJSON did not parse to an object.");

const sub = normalizeSub(subRaw);
const programs = arrayify(org.programs);

const programResults = programs.map(program => evaluateProgram(sub, program));

const eligibleProgramRecordIds = uniq(
  programResults
    .filter(result => result.eligible)
    .map(result => result.progRecordId)
);

const ineligibleProgramRecordIds = uniq(
  programResults
    .filter(result => !result.eligible)
    .map(result => result.progRecordId)
);

const checkedProgramRecordIds = uniq(
  programResults.map(result => result.progRecordId)
);

const eligibleProgramKeys = uniq(
  programResults
    .filter(result => result.eligible)
    .map(result => result.programKEY)
);

const ineligibleProgramKeys = uniq(
  programResults
    .filter(result => !result.eligible)
    .map(result => result.programKEY)
);

const checkedProgramKeys = uniq(
  programResults.map(result => result.programKEY)
);

const hasEligibleProgram = eligibleProgramRecordIds.length > 0;

const alertText = buildAlertText(programResults);
const failSummary = buildFailSummary(programResults);
const omissionSummary = buildOmissionSummary(programResults);

const report = {
  schema: "orgEligibilityReport.v1",
  generatedAt: new Date().toISOString(),

  orgKey: org.orgKey ?? null,
  orgRecordId: org.orgRecordId ?? null,

  subKEY: sub.subKEY ?? null,
  subRecordId: sub.subRecordId ?? null,

  hasEligibleProgram,

  eligibleProgramRecordIds,
  ineligibleProgramRecordIds,
  checkedProgramRecordIds,

  eligibleProgramKeys,
  ineligibleProgramKeys,
  checkedProgramKeys,

  alertText,
  failSummary,
  omissionSummary,

  programResults,
};

/* ---------------- Outputs ---------------- */

const eligibleProgramLinks = eligibleProgramRecordIds.map(id => ({ id }));
const ineligibleProgramLinks = ineligibleProgramRecordIds.map(id => ({ id }));
const checkedProgramLinks = checkedProgramRecordIds.map(id => ({ id }));

output.set("hasEligibleProgram", hasEligibleProgram);

output.set("alertText", alertText);
output.set("failSummary", failSummary);
output.set("omissionSummary", omissionSummary);

output.set("reportJSON", JSON.stringify(report, null, 2));

output.set("eligibleProgramRecordIds", eligibleProgramRecordIds);
output.set("ineligibleProgramRecordIds", ineligibleProgramRecordIds);
output.set("checkedProgramRecordIds", checkedProgramRecordIds);

output.set("eligibleProgramLinks", eligibleProgramLinks);
output.set("ineligibleProgramLinks", ineligibleProgramLinks);
output.set("checkedProgramLinks", checkedProgramLinks);

output.set("eligibleProgramKeys", eligibleProgramKeys);
output.set("ineligibleProgramKeys", ineligibleProgramKeys);
output.set("checkedProgramKeys", checkedProgramKeys);

output.set("orgRecordId", org.orgRecordId || "");
output.set("orgKey", org.orgKey || "");

output.set("subRecordId", sub.subRecordId || "");
output.set("subKEY", sub.subKEY || "");

