/******************************************************
 * Eligibility Engine (Phased, Field-ID based)
 * Auto-pass missing fields + omission reporting
 *
 * INPUTS:
 *   - submissionRecordId (string) REQUIRED
 *   - programsFound      (array)  OPTIONAL (Search records output)
 *
 * OUTPUTS:
 *   - phase1_locationPass (array)
 *   - phase2_incomePass   (array)
 *   - phase3_ownerPass    (array)
 *   - phase4_demoPass     (array) // final qualified
 *   - phase1_locationFail (array)
 *   - phase2_incomeFail   (array)
 *   - phase3_ownerFail    (array)
 *   - phase4_demoFail     (array)
 *   - omissionsByProgram  (object)
 *   - submissionDebug     (object)
 *   - eligibilityReport   (string)
 *
 * ✅ NEW OUTPUTS:
 *   - failsByProgram                (object) // merged fail reasons grouped by program & phase
 *   - failReasonsByProgramText      (string) // long-text friendly, grouped by program
 *   - failReasonsByProgramJsonText  (string) // pretty JSON string (also long-text friendly)
 ******************************************************/

const { submissionRecordId, programsFound } = input.config();
if (!submissionRecordId) throw new Error("Missing input: submissionRecordId");

/* ---------------- CONFIG ---------------- */

const CONFIG = {
  submissionTableId: "tblVSxxZ4uyHZo8Mu",
  programsTableId:   "tblOR9OmQvyMybMGb",

  sub: {
    locationJson:   "fldb1Nr1RLdrEPXvs",
    ownershipJson:  "fldZ8y6PTasDenDFK",
    demoJson:       "fldBnxGyRjMbzW0Gu",
    incomeJson:     "fldooWxtreMrwYaf6",
    applicantName:  "fldHTkg7nTZYKhcVC",
    gisOwner:       "fldUllQLXUJ4COrpq",
  },

  prog: {
    name:           "fldHZ3j3ZUUy7ITEb",
    serviceArea:    "fldVPCPzs8oTrivD9",
    incomeRule:     "fld2Z07Cd7Db0F2qG",
    ownershipRule:  "fldUvbvM0ctQlmH4A",
    demoRule:       "fldlxRsFMf6ADznVo",
  },

  demoRequiredMode: "any", // "any" or "all"
  enforceOwnerMatchWhenOwnHomeRequired: false,
};

/* ---------------- Helpers ---------------- */

function toIdArray(maybeArray) {
  if (!maybeArray || !Array.isArray(maybeArray)) return [];
  return maybeArray
    .map(x => (typeof x === "string" ? x : (x?.id || x?.recordId || x?.airtableRecordId)))
    .filter(Boolean);
}

function firstVal(v) {
  if (Array.isArray(v)) return v.find(x => x !== null && x !== undefined && String(x).trim() !== "") ?? null;
  return (v === undefined ? null : v);
}

function normStr(x) {
  return String(x ?? "")
    .toLowerCase()
    .trim()
    .replace(/[^\p{L}\p{N}\s]+/gu, " ")
    .replace(/\s+/g, " ");
}

function toNumber(x) {
  const s = String(x ?? "").trim();
  if (!s) return NaN;
  const n = Number(s.replace(/[,$\s]/g, ""));
  return Number.isFinite(n) ? n : NaN;
}

function parseBoolMaybe(x) {
  if (x === null || x === undefined) return null;
  if (typeof x === "boolean") return x;
  const s = String(x).trim().toLowerCase();
  if (s === "") return null;
  if (["true","t","yes","y","1"].includes(s)) return true;
  if (["false","f","no","n","0"].includes(s)) return false;
  return null;
}

function parseJsonMaybe(v) {
  if (v === null || v === undefined) return null;

  // Native Airtable arrays from lookup fields
  if (Array.isArray(v)) {
    const parsed = v
      .map(item => {
        try { return parseJsonMaybe(item); } catch { return null; }
      })
      .filter(Boolean);

    return parsed.length ? parsed[parsed.length - 1] : null;
  }

  if (typeof v === "object") return v;

  let s = String(v).trim();
  if (!s) return null;

  // Direct JSON
  try { return JSON.parse(s); } catch {}

  // Quoted / escaped JSON string
  try {
    const unwrapped = JSON.parse(s);
    if (unwrapped && typeof unwrapped === "object") return unwrapped;
    if (typeof unwrapped === "string") {
      s = unwrapped.trim();
      try { return JSON.parse(s); } catch {}
    }
  } catch {}

  // Comma-separated top-level JSON values:
  //   {...}, {...}
  // or
  //   {...}, {...}, {...}
  try {
    const arr = JSON.parse(`[${s}]`).filter(Boolean);
    return arr.length ? arr[arr.length - 1] : null;
  } catch {}

  throw new Error(`Invalid JSON payload: ${s.slice(0, 300)}`);
}

function arrayify(x) { return Array.isArray(x) ? x : (x ? [x] : []); }
function safeString(v) {
  if (v === null || v === undefined) return "";
  return String(v);
}

function safeJsonString(v) {
  if (v === null || v === undefined) return "";
  try {
    return JSON.stringify(v, null, 2);
  } catch {
    return "";
  }
}
/* ---------------- Tables/Fields by ID ---------------- */

const subTable = base.getTable(CONFIG.submissionTableId);
const progTable = base.getTable(CONFIG.programsTableId);

function F(table, fieldId) {
  return fieldId || null;
}

const SUB_FIELDS = {
  locationJson:  F(subTable, CONFIG.sub.locationJson),
  ownershipJson: F(subTable, CONFIG.sub.ownershipJson),
  demoJson:      F(subTable, CONFIG.sub.demoJson),
  incomeJson:    F(subTable, CONFIG.sub.incomeJson),
  applicantName: CONFIG.sub.applicantName ? F(subTable, CONFIG.sub.applicantName) : null,
  gisOwner:      CONFIG.sub.gisOwner ? F(subTable, CONFIG.sub.gisOwner) : null,
};

const PROG_FIELDS = {
  name:          F(progTable, CONFIG.prog.name),
  serviceArea:   F(progTable, CONFIG.prog.serviceArea),
  incomeRule:    F(progTable, CONFIG.prog.incomeRule),
  ownershipRule: F(progTable, CONFIG.prog.ownershipRule),
  demoRule:      F(progTable, CONFIG.prog.demoRule),
};

/* ---------------- Normalize Submission ---------------- */

function normalizeSubmission(subRec) {
  const locObj = parseJsonMaybe(subRec.getCellValue(SUB_FIELDS.locationJson)) || {};
  const ownObj = parseJsonMaybe(subRec.getCellValue(SUB_FIELDS.ownershipJson)) || {};
  const demoObj = parseJsonMaybe(subRec.getCellValue(SUB_FIELDS.demoJson)) || {};
  const incomeObj = parseJsonMaybe(subRec.getCellValue(SUB_FIELDS.incomeJson)) || [];

  const loc = locObj.serviceArea ?? locObj.location ?? locObj ?? {};
  const location = {
    state: (loc.state ?? "").toString(),
    county: (loc.county ?? "").toString(),
    city: (loc.city ?? loc.town ?? "").toString(),
    coa: parseBoolMaybe(loc.coa),
    neighborhood: (loc.neighborhood ?? loc.legacy ?? "").toString(),
  };

  const oc = ownObj.ownershipCheck ?? ownObj ?? {};
  const ownership = {
    typeHome: (oc.typeHome ?? oc.homeType ?? "").toString(),
    bldgValue: toNumber(oc.bldgValue ?? oc.blsgValue),
    primaryRes: parseBoolMaybe(oc.primaryRes),
    ownHome: parseBoolMaybe(oc.ownHome),
    ownLot: parseBoolMaybe(oc.ownLot),
    minTime: toNumber(oc.minTime),
  };

  const dc = demoObj.demoCheck ?? demoObj.demoGroup ?? demoObj ?? {};
  const demoSet = new Set(
    Object.entries(dc)
      .filter(([,v]) => parseBoolMaybe(v) === true)
      .map(([k]) => String(k).trim())
  );

  const incomeArr = arrayify(incomeObj).map(r => r?.incomeCheck ?? r).filter(Boolean);
  const incomeMap = {};
  for (const r of incomeArr) {
    const calc = String(r.calc ?? "").trim().toUpperCase();
    const pct = toNumber(r.percent);
    if (calc && Number.isFinite(pct)) incomeMap[calc] = pct;
  }

  const applicantName = SUB_FIELDS.applicantName ? (subRec.getCellValueAsString(SUB_FIELDS.applicantName) || "") : "";
  const gisOwner = SUB_FIELDS.gisOwner ? (subRec.getCellValueAsString(SUB_FIELDS.gisOwner) || "") : "";

  return { location, ownership, demoSet, incomeMap, applicantName, gisOwner };
}

/* ---------------- Normalize Program ---------------- */

function normalizeProgram(rec) {
  const name = rec.getCellValueAsString(PROG_FIELDS.name);

  const saObj = parseJsonMaybe(rec.getCellValue(PROG_FIELDS.serviceArea)) || {};
  const saArr = arrayify(saObj.serviceArea ?? saObj ?? []);
  const serviceArea = new Map(); // scale -> Set(normStr(specific))
  for (const item of saArr) {
    const scale = normStr(item.scale ?? item.key ?? "");
    const specific = String(item.specific ?? item.value ?? "").trim();
    if (!scale || !specific) continue;
    if (!serviceArea.has(scale)) serviceArea.set(scale, new Set());
    serviceArea.get(scale).add(normStr(specific));
  }

  const incObj = parseJsonMaybe(rec.getCellValue(PROG_FIELDS.incomeRule)) || {};
  const ic = incObj.incomeCheck ?? incObj ?? {};
  const incomeRule = {
    calc: String(ic.calc ?? "").trim().toUpperCase(),
    max: toNumber(ic.max),
  };

  const ownObj = parseJsonMaybe(rec.getCellValue(PROG_FIELDS.ownershipRule)) || {};
  const ownChecks = arrayify(
    ownObj.ownershipChecks ?? (ownObj.ownershipCheck ? [{ ownershipCheck: ownObj.ownershipCheck }] : [])
  ).map(x => x?.ownershipCheck ?? x).filter(Boolean);

  const demoObj = parseJsonMaybe(rec.getCellValue(PROG_FIELDS.demoRule)) || null;
  let demoRule = null;
  if (demoObj) {
    const qual = String(demoObj.demoQual ?? "").trim(); // Required/Prioritized
    const group = demoObj.demoGroup ?? demoObj.demoCheck ?? demoObj.demoCodes ?? {};
    const codes = Object.entries(group)
      .filter(([,v]) => parseBoolMaybe(v) === true)
      .map(([k]) => String(k).trim());
    if (qual && codes.length) demoRule = { qual, codes };
  }

  return { id: rec.id, name, serviceArea, incomeRule, ownershipChecks: ownChecks, demoRule };
}

/* ---------------- Omission tracking ---------------- */

function addOmission(omissionsByProgram, prog, phase, msg) {
  if (!omissionsByProgram[prog.id]) {
    omissionsByProgram[prog.id] = { program: prog.name, programId: prog.id, items: [] };
  }
  omissionsByProgram[prog.id].items.push(`${phase}: ${msg}`);
}

/* ---------------- Phase checks (auto-pass missing) ---------------- */

function checkScale(programMap, scaleKey, submissionValue) {
  const allowed = programMap.get(normStr(scaleKey));
  if (!allowed || allowed.size === 0) return { enforced: false, pass: true };

  const sv = String(submissionValue ?? "").trim();
  if (!sv) return { enforced: true, pass: true, missingSubmission: true, allowed: Array.from(allowed) };

  const pass = allowed.has(normStr(sv));
  return { enforced: true, pass, allowed: Array.from(allowed), actual: sv };
}

function phase1_location(sub, prog, omissionsByProgram) {
  // State
  {
    const r = checkScale(prog.serviceArea, "state", sub.location.state);
    if (!r.enforced) addOmission(omissionsByProgram, prog, "phase1📍", "program omitted state restriction");
    else if (r.missingSubmission) addOmission(omissionsByProgram, prog, "phase1📍", "submission missing state (auto-pass)");
    else if (!r.pass) return { pass: false, fails: [{ check:"state", actual:r.actual, allowed:r.allowed }] };
  }

  // County
  {
    const r = checkScale(prog.serviceArea, "county", sub.location.county);
    if (!r.enforced) addOmission(omissionsByProgram, prog, "phase1📍", "program omitted county restriction");
    else if (r.missingSubmission) addOmission(omissionsByProgram, prog, "phase1📍", "submission missing county (auto-pass)");
    else if (!r.pass) return { pass: false, fails: [{ check:"county", actual:r.actual, allowed:r.allowed }] };
  }

  // City / town
  {
    const cityAllowed = prog.serviceArea.get("city");
    const townAllowed = prog.serviceArea.get("town");
    const enforced = (cityAllowed && cityAllowed.size) || (townAllowed && townAllowed.size);

    if (!enforced) {
      addOmission(omissionsByProgram, prog, "phase1📍", "program omitted city/town restriction");
    } else {
      const sv = String(sub.location.city ?? "").trim();
      if (!sv) {
        addOmission(omissionsByProgram, prog, "phase1📍", "submission missing city/town (auto-pass)");
      } else {
        const ok =
          (cityAllowed && cityAllowed.has(normStr(sv))) ||
          (townAllowed && townAllowed.has(normStr(sv)));
        if (!ok) {
          return {
            pass: false,
            fails: [{
              check: "city/town",
              actual: sv,
              allowed: [
                ...(cityAllowed ? Array.from(cityAllowed) : []),
                ...(townAllowed ? Array.from(townAllowed) : []),
              ],
            }],
          };
        }
      }
    }
  }

  // COA
  {
    const coaAllowed = prog.serviceArea.get("coa");
    if (!coaAllowed || !coaAllowed.size) {
      addOmission(omissionsByProgram, prog, "phase1📍", "program omitted coa restriction");
    } else {
      const wantTrue = coaAllowed.has("true") || coaAllowed.has("yes");
      if (sub.location.coa === null) {
        addOmission(omissionsByProgram, prog, "phase1📍", "submission missing coa (auto-pass)");
      } else if (wantTrue && sub.location.coa !== true) {
        return { pass: false, fails: [{ check:"coa", actual: sub.location.coa, expected:true }] };
      }
    }
  }

  // Neighborhood / legacy
  {
    const r = checkScale(prog.serviceArea, "neighborhood", sub.location.neighborhood);
    const r2 = checkScale(prog.serviceArea, "legacy", sub.location.neighborhood);
    const enforced = r.enforced || r2.enforced;

    if (!enforced) {
      addOmission(omissionsByProgram, prog, "phase1📍", "program omitted neighborhood/legacy restriction");
    } else {
      const sv = String(sub.location.neighborhood ?? "").trim();
      if (!sv) {
        addOmission(omissionsByProgram, prog, "phase1📍", "submission missing neighborhood/legacy (auto-pass)");
      } else {
        const allowed = [
          ...(prog.serviceArea.get("neighborhood") ? Array.from(prog.serviceArea.get("neighborhood")) : []),
          ...(prog.serviceArea.get("legacy") ? Array.from(prog.serviceArea.get("legacy")) : []),
        ];
        const ok = allowed.includes(normStr(sv));
        if (!ok) return { pass: false, fails: [{ check:"neighborhood/legacy", actual: sv, allowed }] };
      }
    }
  }

  return { pass: true };
}

function phase2_income(sub, prog, omissionsByProgram) {
  const { calc, max } = prog.incomeRule;
  if (!calc || !Number.isFinite(max)) {
    addOmission(omissionsByProgram, prog, "phase2💲", "program omitted income rule");
    return { pass: true };
  }

  const pct = sub.incomeMap[calc];
  if (!Number.isFinite(pct)) {
    addOmission(omissionsByProgram, prog, "phase2💲", `submission missing ${calc}% (auto-pass)`);
    return { pass: true };
  }

  if (pct <= max) return { pass: true };
  return { pass: false, fails: [{ check:`income:${calc}`, actual:pct, expected:`<= ${max}` }] };
}

function ownershipRulePasses(sub, prog, rule, omissionsByProgram) {
  const fails = [];

  // typeHome list
  if (Array.isArray(rule.typeHome) && rule.typeHome.length) {
    const sv = String(sub.ownership.typeHome ?? "").trim();
    if (!sv) {
      addOmission(omissionsByProgram, prog, "phase3🏡", "submission missing typeHome (auto-pass)");
    } else {
      const allowed = rule.typeHome.map(normStr);
      if (!allowed.includes(normStr(sv))) fails.push({ check:"typeHome", actual: sv, allowed: rule.typeHome });
    }
  } else {
    addOmission(omissionsByProgram, prog, "phase3🏡", "program omitted typeHome restriction");
  }

  // bldgValue max
  if (rule.bldgValue !== undefined && rule.bldgValue !== null && String(rule.bldgValue) !== "") {
    const maxVal = toNumber(rule.bldgValue);
    const subVal = sub.ownership.bldgValue;
    if (!Number.isFinite(subVal)) {
      addOmission(omissionsByProgram, prog, "phase3🏡", "submission missing bldgValue (auto-pass)");
    } else if (Number.isFinite(maxVal) && subVal > maxVal) {
      fails.push({ check:"bldgValue", actual: subVal, expected:`<= ${maxVal}` });
    }
  } else {
    addOmission(omissionsByProgram, prog, "phase3🏡", "program omitted bldgValue restriction");
  }

  // booleans
  for (const k of ["primaryRes","ownHome","ownLot"]) {
    if (rule[k] === true || rule[k] === false) {
      if (sub.ownership[k] === null) {
        addOmission(omissionsByProgram, prog, "phase3🏡", `submission missing ${k} (auto-pass)`);
      } else if (sub.ownership[k] !== rule[k]) {
        fails.push({ check:k, actual: sub.ownership[k], expected: rule[k] });
      }
    } else {
      addOmission(omissionsByProgram, prog, "phase3🏡", `program omitted ${k} restriction`);
    }
  }

  // minTime
  if (rule.minTime !== undefined && rule.minTime !== null && String(rule.minTime) !== "") {
    const minT = toNumber(rule.minTime);
    const subT = sub.ownership.minTime;
    if (!Number.isFinite(subT)) {
      addOmission(omissionsByProgram, prog, "phase3🏡", "submission missing minTime (auto-pass)");
    } else if (Number.isFinite(minT) && subT < minT) {
      fails.push({ check:"minTime", actual: subT, expected:`>= ${minT}` });
    }
  } else {
    addOmission(omissionsByProgram, prog, "phase3🏡", "program omitted minTime restriction");
  }

  // optional owner match
  if (CONFIG.enforceOwnerMatchWhenOwnHomeRequired && rule.ownHome === true) {
    const a = normStr(sub.applicantName);
    const o = normStr(sub.gisOwner);
    if (!a || !o) {
      addOmission(omissionsByProgram, prog, "phase3🏡", "submission missing applicantName or gisOwner (auto-pass owner match)");
    } else {
      const aTok = new Set(a.split(" ").filter(t => t.length >= 3));
      const oTok = new Set(o.split(" ").filter(t => t.length >= 3));
      let hit = 0;
      for (const t of aTok) if (oTok.has(t)) hit++;
      if (hit < 1) fails.push({ check:"gisOwner vs applicantName", applicantName: sub.applicantName, gisOwner: sub.gisOwner });
    }
  }

  return { pass: fails.length === 0, fails };
}

function phase3_ownership(sub, prog, omissionsByProgram) {
  if (!prog.ownershipChecks.length) {
    addOmission(omissionsByProgram, prog, "phase3🏡", "program omitted ownership rules entirely");
    return { pass: true };
  }

  const attempts = prog.ownershipChecks.map(rule => ownershipRulePasses(sub, prog, rule, omissionsByProgram));
  if (attempts.some(a => a.pass)) return { pass: true };
  return { pass: false, fails: attempts.flatMap(a => a.fails || []) };
}

function phase4_demo(sub, prog, omissionsByProgram) {
  if (!prog.demoRule) {
    addOmission(omissionsByProgram, prog, "phase4👤", "program omitted demographic rule");
    return { pass: true };
  }

  const { qual, codes } = prog.demoRule;
  const hits = codes.filter(c => sub.demoSet.has(c));

  if (qual.toLowerCase() === "required") {
    if (!sub.demoSet || sub.demoSet.size === 0) {
      addOmission(omissionsByProgram, prog, "phase4👤", "submission missing demo flags (auto-pass required demo)");
      return { pass: true };
    }

    if (CONFIG.demoRequiredMode === "all") {
      const pass = hits.length === codes.length;
      return pass ? { pass: true } : { pass: false, fails: [{ check:"demo(required:all)", required: codes, hits }] };
    } else {
      const pass = hits.length > 0;
      return pass ? { pass: true } : { pass: false, fails: [{ check:"demo(required:any)", required: codes, hits }] };
    }
  }

  return { pass: true, prioritized: true, hits, required: codes };
}

/* ---------------- Fail reporting helpers ---------------- */

function tallyFailChecks(failArray) {
  const counts = {};
  for (const row of (failArray || [])) {
    for (const f of (row.fails || [])) {
      const k = String(f.check || "unknown");
      counts[k] = (counts[k] || 0) + 1;
    }
  }
  return Object.entries(counts).sort((a,b) => b[1] - a[1]);
}

function formatTopFailChecks(failArray, limit = 10) {
  const tallied = tallyFailChecks(failArray).slice(0, limit);
  if (!tallied.length) return "(none)";
  return tallied.map(([k, n]) => `- ${k}: ${n}`).join("\n");
}

function formatFailExamples(failArray, limitPrograms = 5) {
  const slice = (failArray || []).slice(0, limitPrograms);
  if (!slice.length) return "(none)";
  return slice.map(x => {
    const first = (x.fails || [])[0] || {};
    const extra =
      first.expected !== undefined ? ` expected ${first.expected}` :
      first.allowed ? ` allowed ${JSON.stringify(first.allowed)}` : "";
    const got = first.actual !== undefined ? ` got ${JSON.stringify(first.actual)}` : "";
    return `- ${x.program}: ${first.check || "unknown"}${extra}${got}`;
  }).join("\n");
}

/* ---------------- ✅ NEW: Fail reasons (by program) ---------------- */

function addFailsByProgram(failsByProgram, phaseLabel, failArray) {
  for (const row of (failArray || [])) {
    const pid = row.programId || row.programID || row.id;
    if (!pid) continue;

    if (!failsByProgram[pid]) {
      failsByProgram[pid] = {
        program: row.program || "(unknown program)",
        programId: pid,
        phases: {},
      };
    }

    if (!failsByProgram[pid].phases[phaseLabel]) failsByProgram[pid].phases[phaseLabel] = [];
    failsByProgram[pid].phases[phaseLabel].push(...(row.fails || []));
  }
}

function formatOneFail(f) {
  if (!f || typeof f !== "object") return String(f);

  const parts = [];
  parts.push(String(f.check || "unknown"));

  if ("expected" in f) parts.push(`expected: ${JSON.stringify(f.expected)}`);
  if ("allowed" in f) parts.push(`allowed: ${JSON.stringify(f.allowed)}`);
  if ("actual" in f) parts.push(`actual: ${JSON.stringify(f.actual)}`);

  if ("required" in f) parts.push(`required: ${JSON.stringify(f.required)}`);
  if ("hits" in f) parts.push(`hits: ${JSON.stringify(f.hits)}`);

  if ("applicantName" in f) parts.push(`applicantName: ${JSON.stringify(f.applicantName)}`);
  if ("gisOwner" in f) parts.push(`gisOwner: ${JSON.stringify(f.gisOwner)}`);

  return parts.join(" | ");
}

function formatFailsByProgramText(failsByProgram) {
  const progs = Object.values(failsByProgram || {})
    .sort((a, b) => String(a.program).localeCompare(String(b.program)));

  if (!progs.length) return "(none)";

  return progs.map(p => {
    const phaseBlocks = Object.entries(p.phases || {})
      .filter(([, arr]) => Array.isArray(arr) && arr.length)
      .map(([phase, arr]) => {
        const lines = arr.map(x => `  - ${formatOneFail(x)}`).join("\n");
        return `${phase}:\n${lines}`;
      })
      .join("\n");

    return `[${p.program}] (${p.programId})\n${phaseBlocks || "(no fails recorded)"}`;
  }).join("\n\n");
}

function clampText(s, maxChars = 90000) {
  const str = String(s ?? "");
  if (str.length <= maxChars) return str;
  return str.slice(0, maxChars - 40) + "\n...(truncated due to length)";
}
[
  "phase1_locationPass",
  "phase2_incomePass",
  "phase3_ownerPass",
  "phase4_demoPass",
  "phase1_locationFail",
  "phase2_incomeFail",
  "phase3_ownerFail",
  "phase4_demoFail",
  "omissionsByProgram",
  "failsByProgram",
  "submissionDebug",
  "eligibilityReport",
  "failReasonsByProgramText",
  "failReasonsByProgramJsonText",
  "locationDebug",
].forEach(name => output.set(name, ""));
/* ---------------- MAIN ---------------- */

const omissionsByProgram = {};

// fail arrays
const phase1_locationFail = [];
const phase2_incomeFail = [];
const phase3_ownerFail = [];
const phase4_demoFail = [];

// Load submission
const subRec = await subTable.selectRecordAsync(submissionRecordId, {
  fields: Object.values(SUB_FIELDS).filter(Boolean),
});
if (!subRec) throw new Error(`Submission record not found: ${submissionRecordId}`);

const sub = normalizeSubmission(subRec);
//output.set("locationDebug", sub.location);

// Load programs once
const programIds = new Set(toIdArray(programsFound));
const progQuery = await progTable.selectRecordsAsync({
  fields: Object.values(PROG_FIELDS),
});
const allPrograms = progQuery.records
  .filter(r => programIds.size === 0 || programIds.has(r.id))
  .map(normalizeProgram);

// Phase 1 📍
const phase1_locationPass = [];
const phase1Programs = [];
for (const p of allPrograms) {
  const r = phase1_location(sub, p, omissionsByProgram);
  if (r.pass) {
    phase1_locationPass.push({ program: p.name, programId: p.id });
    phase1Programs.push(p);
  } else {
    phase1_locationFail.push({ program: p.name, programId: p.id, fails: r.fails || [] });
  }
}

// Phase 2 💲
const phase2_incomePass = [];
const phase2Programs = [];
for (const p of phase1Programs) {
  const r = phase2_income(sub, p, omissionsByProgram);
  if (r.pass) {
    phase2_incomePass.push({ program: p.name, programId: p.id });
    phase2Programs.push(p);
  } else {
    phase2_incomeFail.push({ program: p.name, programId: p.id, fails: r.fails || [] });
  }
}

// Phase 3 🏡
const phase3_ownerPass = [];
const phase3Programs = [];
for (const p of phase2Programs) {
  const r = phase3_ownership(sub, p, omissionsByProgram);
  if (r.pass) {
    phase3_ownerPass.push({ program: p.name, programId: p.id });
    phase3Programs.push(p);
  } else {
    phase3_ownerFail.push({ program: p.name, programId: p.id, fails: r.fails || [] });
  }
}

// Phase 4 👤
const phase4_demoPass = [];
for (const p of phase3Programs) {
  const r = phase4_demo(sub, p, omissionsByProgram);
  if (r.pass) {
    phase4_demoPass.push({ program: p.name, programId: p.id, prioritized: !!r.prioritized });
  } else {
    phase4_demoFail.push({ program: p.name, programId: p.id, fails: r.fails || [] });
  }
}

// ✅ NEW: Fail reasons by program (merged across phases)
const failsByProgram = {};
addFailsByProgram(failsByProgram, "phase1📍", phase1_locationFail);
addFailsByProgram(failsByProgram, "phase2💲", phase2_incomeFail);
addFailsByProgram(failsByProgram, "phase3🏡", phase3_ownerFail);
addFailsByProgram(failsByProgram, "phase4👤", phase4_demoFail);

const failReasonsByProgramText = clampText(formatFailsByProgramText(failsByProgram));
const failReasonsByProgramJsonText = clampText(JSON.stringify(failsByProgram, null, 2));

// Report
const qualifiedNames = phase4_demoPass.map(x => x.program);

const omittedLines = Object.values(omissionsByProgram)
  .map(o => `\n[${o.program}]\n- ` + o.items.join("\n- "))
  .join("\n");

const failSummary =
  `\n---\nFail check summary (count of programs failing each check):\n` +
  `\nPhase1📍:\n${formatTopFailChecks(phase1_locationFail)}` +
  `\n\nPhase2💲:\n${formatTopFailChecks(phase2_incomeFail)}` +
  `\n\nPhase3🏡:\n${formatTopFailChecks(phase3_ownerFail)}` +
  `\n\nPhase4👤:\n${formatTopFailChecks(phase4_demoFail)}` +
  `\n\nExamples (first few Phase3🏡 failures):\n${formatFailExamples(phase3_ownerFail, 8)}\n`;

const eligibilityReport =
  `Phase1📍 pass: ${phase1_locationPass.length}\n` +
  `Phase2💲 pass: ${phase2_incomePass.length}\n` +
  `Phase3🏡 pass: ${phase3_ownerPass.length}\n` +
  `Phase4👤 pass: ${phase4_demoPass.length}\n\n` +
  (qualifiedNames.length
    ? `✅ Qualified:\n- ${qualifiedNames.join("\n- ")}\n`
    : "❌ No programs matched.\n") +
  `\n---\nRestrictions omitted / auto-passed (by program):\n` +
  (omittedLines.trim() ? omittedLines : "\n(none)") +
  failSummary +
  `\n---\nFail reasons (by program):\n` +
  failReasonsByProgramText +
  `\n`;
// Build debug object once
const submissionDebug = {
  location: sub.location,
  ownership: sub.ownership,
  incomeMap: sub.incomeMap,
  demoCodes: Array.from(sub.demoSet),
  applicantName: sub.applicantName,
  gisOwner: sub.gisOwner,
};

// Outputs as STRINGS only
output.set("locationDebug", safeJsonString(sub.location));

output.set("phase1_locationPass", safeJsonString(phase1_locationPass));
output.set("phase2_incomePass", safeJsonString(phase2_incomePass));
output.set("phase3_ownerPass", safeJsonString(phase3_ownerPass));
output.set("phase4_demoPass", safeJsonString(phase4_demoPass));

output.set("phase1_locationFail", safeJsonString(phase1_locationFail));
output.set("phase2_incomeFail", safeJsonString(phase2_incomeFail));
output.set("phase3_ownerFail", safeJsonString(phase3_ownerFail));
output.set("phase4_demoFail", safeJsonString(phase4_demoFail));

output.set("omissionsByProgram", safeJsonString(omissionsByProgram));
output.set("failsByProgram", safeJsonString(failsByProgram));
output.set("submissionDebug", safeJsonString(submissionDebug));

output.set("failReasonsByProgramText", safeString(failReasonsByProgramText));
output.set("failReasonsByProgramJsonText", safeString(failReasonsByProgramJsonText));
output.set("eligibilityReport", safeString(eligibilityReport));

console.log(sub);

script:
/******************************************************
 * Eligibility Engine (Phased, Field-ID based)
 * Auto-pass missing fields + omission reporting
 *
 * INPUTS:
 *   - submissionRecordId (string) REQUIRED
 *   - programsFound      (array)  OPTIONAL (Search records output)
 *
 * OUTPUTS:
 *   - phase1_locationPass (array)
 *   - phase2_incomePass   (array)
 *   - phase3_ownerPass    (array)
 *   - phase4_demoPass     (array) // final qualified
 *   - phase1_locationFail (array)
 *   - phase2_incomeFail   (array)
 *   - phase3_ownerFail    (array)
 *   - phase4_demoFail     (array)
 *   - omissionsByProgram  (object)
 *   - submissionDebug     (object)
 *   - eligibilityReport   (string)
 *
 * ✅ NEW OUTPUTS:
 *   - failsByProgram                (object) // merged fail reasons grouped by program & phase
 *   - failReasonsByProgramText      (string) // long-text friendly, grouped by program
 *   - failReasonsByProgramJsonText  (string) // pretty JSON string (also long-text friendly)
 ******************************************************/

const { submissionRecordId, programsFound } = input.config();
if (!submissionRecordId) throw new Error("Missing input: submissionRecordId");

/* ---------------- CONFIG ---------------- */

const CONFIG = {
  submissionTableId: "tblVSxxZ4uyHZo8Mu",
  programsTableId:   "tblOR9OmQvyMybMGb",

  sub: {
    locationJson:   "fldb1Nr1RLdrEPXvs",
    ownershipJson:  "fldZ8y6PTasDenDFK",
    demoJson:       "fldBnxGyRjMbzW0Gu",
    incomeJson:     "fldooWxtreMrwYaf6",
    applicantName:  "fldHTkg7nTZYKhcVC",
    gisOwner:       "fldUllQLXUJ4COrpq",
  },

  prog: {
    name:           "fldHZ3j3ZUUy7ITEb",
    serviceArea:    "fldVPCPzs8oTrivD9",
    incomeRule:     "fld2Z07Cd7Db0F2qG",
    ownershipRule:  "fldUvbvM0ctQlmH4A",
    demoRule:       "fldlxRsFMf6ADznVo",
  },

  demoRequiredMode: "any", // "any" or "all"
  enforceOwnerMatchWhenOwnHomeRequired: false,
};

/* ---------------- Helpers ---------------- */

function toIdArray(maybeArray) {
  if (!maybeArray || !Array.isArray(maybeArray)) return [];
  return maybeArray
    .map(x => (typeof x === "string" ? x : (x?.id || x?.recordId || x?.airtableRecordId)))
    .filter(Boolean);
}

function firstVal(v) {
  if (Array.isArray(v)) return v.find(x => x !== null && x !== undefined && String(x).trim() !== "") ?? null;
  return (v === undefined ? null : v);
}

function normStr(x) {
  return String(x ?? "")
    .toLowerCase()
    .trim()
    .replace(/[^\p{L}\p{N}\s]+/gu, " ")
    .replace(/\s+/g, " ");
}

function toNumber(x) {
  const s = String(x ?? "").trim();
  if (!s) return NaN;
  const n = Number(s.replace(/[,$\s]/g, ""));
  return Number.isFinite(n) ? n : NaN;
}

function parseBoolMaybe(x) {
  if (x === null || x === undefined) return null;
  if (typeof x === "boolean") return x;
  const s = String(x).trim().toLowerCase();
  if (s === "") return null;
  if (["true","t","yes","y","1"].includes(s)) return true;
  if (["false","f","no","n","0"].includes(s)) return false;
  return null;
}

function parseJsonMaybe(v) {
  if (v === null || v === undefined) return null;

  // Native Airtable arrays from lookup fields
  if (Array.isArray(v)) {
    const parsed = v
      .map(item => {
        try { return parseJsonMaybe(item); } catch { return null; }
      })
      .filter(Boolean);

    return parsed.length ? parsed[parsed.length - 1] : null;
  }

  if (typeof v === "object") return v;

  let s = String(v).trim();
  if (!s) return null;

  // Direct JSON
  try { return JSON.parse(s); } catch {}

  // Quoted / escaped JSON string
  try {
    const unwrapped = JSON.parse(s);
    if (unwrapped && typeof unwrapped === "object") return unwrapped;
    if (typeof unwrapped === "string") {
      s = unwrapped.trim();
      try { return JSON.parse(s); } catch {}
    }
  } catch {}

  // Comma-separated top-level JSON values:
  //   {...}, {...}
  // or
  //   {...}, {...}, {...}
  try {
    const arr = JSON.parse(`[${s}]`).filter(Boolean);
    return arr.length ? arr[arr.length - 1] : null;
  } catch {}

  throw new Error(`Invalid JSON payload: ${s.slice(0, 300)}`);
}

function arrayify(x) { return Array.isArray(x) ? x : (x ? [x] : []); }
function safeString(v) {
  if (v === null || v === undefined) return "";
  return String(v);
}

function safeJsonString(v) {
  if (v === null || v === undefined) return "";
  try {
    return JSON.stringify(v, null, 2);
  } catch {
    return "";
  }
}
/* ---------------- Tables/Fields by ID ---------------- */

const subTable = base.getTable(CONFIG.submissionTableId);
const progTable = base.getTable(CONFIG.programsTableId);

function F(table, fieldId) {
  return fieldId || null;
}

const SUB_FIELDS = {
  locationJson:  F(subTable, CONFIG.sub.locationJson),
  ownershipJson: F(subTable, CONFIG.sub.ownershipJson),
  demoJson:      F(subTable, CONFIG.sub.demoJson),
  incomeJson:    F(subTable, CONFIG.sub.incomeJson),
  applicantName: CONFIG.sub.applicantName ? F(subTable, CONFIG.sub.applicantName) : null,
  gisOwner:      CONFIG.sub.gisOwner ? F(subTable, CONFIG.sub.gisOwner) : null,
};

const PROG_FIELDS = {
  name:          F(progTable, CONFIG.prog.name),
  serviceArea:   F(progTable, CONFIG.prog.serviceArea),
  incomeRule:    F(progTable, CONFIG.prog.incomeRule),
  ownershipRule: F(progTable, CONFIG.prog.ownershipRule),
  demoRule:      F(progTable, CONFIG.prog.demoRule),
};

/* ---------------- Normalize Submission ---------------- */

function normalizeSubmission(subRec) {
  const locObj = parseJsonMaybe(subRec.getCellValue(SUB_FIELDS.locationJson)) || {};
  const ownObj = parseJsonMaybe(subRec.getCellValue(SUB_FIELDS.ownershipJson)) || {};
  const demoObj = parseJsonMaybe(subRec.getCellValue(SUB_FIELDS.demoJson)) || {};
  const incomeObj = parseJsonMaybe(subRec.getCellValue(SUB_FIELDS.incomeJson)) || [];

  const loc = locObj.serviceArea ?? locObj.location ?? locObj ?? {};
  const location = {
    state: (loc.state ?? "").toString(),
    county: (loc.county ?? "").toString(),
    city: (loc.city ?? loc.town ?? "").toString(),
    coa: parseBoolMaybe(loc.coa),
    neighborhood: (loc.neighborhood ?? loc.legacy ?? "").toString(),
  };

  const oc = ownObj.ownershipCheck ?? ownObj ?? {};
  const ownership = {
    typeHome: (oc.typeHome ?? oc.homeType ?? "").toString(),
    bldgValue: toNumber(oc.bldgValue ?? oc.blsgValue),
    primaryRes: parseBoolMaybe(oc.primaryRes),
    ownHome: parseBoolMaybe(oc.ownHome),
    ownLot: parseBoolMaybe(oc.ownLot),
    minTime: toNumber(oc.minTime),
  };

  const dc = demoObj.demoCheck ?? demoObj.demoGroup ?? demoObj ?? {};
  const demoSet = new Set(
    Object.entries(dc)
      .filter(([,v]) => parseBoolMaybe(v) === true)
      .map(([k]) => String(k).trim())
  );

  const incomeArr = arrayify(incomeObj).map(r => r?.incomeCheck ?? r).filter(Boolean);
  const incomeMap = {};
  for (const r of incomeArr) {
    const calc = String(r.calc ?? "").trim().toUpperCase();
    const pct = toNumber(r.percent);
    if (calc && Number.isFinite(pct)) incomeMap[calc] = pct;
  }

  const applicantName = SUB_FIELDS.applicantName ? (subRec.getCellValueAsString(SUB_FIELDS.applicantName) || "") : "";
  const gisOwner = SUB_FIELDS.gisOwner ? (subRec.getCellValueAsString(SUB_FIELDS.gisOwner) || "") : "";

  return { location, ownership, demoSet, incomeMap, applicantName, gisOwner };
}

/* ---------------- Normalize Program ---------------- */

function normalizeProgram(rec) {
  const name = rec.getCellValueAsString(PROG_FIELDS.name);

  const saObj = parseJsonMaybe(rec.getCellValue(PROG_FIELDS.serviceArea)) || {};
  const saArr = arrayify(saObj.serviceArea ?? saObj ?? []);
  const serviceArea = new Map(); // scale -> Set(normStr(specific))
  for (const item of saArr) {
    const scale = normStr(item.scale ?? item.key ?? "");
    const specific = String(item.specific ?? item.value ?? "").trim();
    if (!scale || !specific) continue;
    if (!serviceArea.has(scale)) serviceArea.set(scale, new Set());
    serviceArea.get(scale).add(normStr(specific));
  }

  const incObj = parseJsonMaybe(rec.getCellValue(PROG_FIELDS.incomeRule)) || {};
  const ic = incObj.incomeCheck ?? incObj ?? {};
  const incomeRule = {
    calc: String(ic.calc ?? "").trim().toUpperCase(),
    max: toNumber(ic.max),
  };

  const ownObj = parseJsonMaybe(rec.getCellValue(PROG_FIELDS.ownershipRule)) || {};
  const ownChecks = arrayify(
    ownObj.ownershipChecks ?? (ownObj.ownershipCheck ? [{ ownershipCheck: ownObj.ownershipCheck }] : [])
  ).map(x => x?.ownershipCheck ?? x).filter(Boolean);

  const demoObj = parseJsonMaybe(rec.getCellValue(PROG_FIELDS.demoRule)) || null;
  let demoRule = null;
  if (demoObj) {
    const qual = String(demoObj.demoQual ?? "").trim(); // Required/Prioritized
    const group = demoObj.demoGroup ?? demoObj.demoCheck ?? demoObj.demoCodes ?? {};
    const codes = Object.entries(group)
      .filter(([,v]) => parseBoolMaybe(v) === true)
      .map(([k]) => String(k).trim());
    if (qual && codes.length) demoRule = { qual, codes };
  }

  return { id: rec.id, name, serviceArea, incomeRule, ownershipChecks: ownChecks, demoRule };
}

/* ---------------- Omission tracking ---------------- */

function addOmission(omissionsByProgram, prog, phase, msg) {
  if (!omissionsByProgram[prog.id]) {
    omissionsByProgram[prog.id] = { program: prog.name, programId: prog.id, items: [] };
  }
  omissionsByProgram[prog.id].items.push(`${phase}: ${msg}`);
}

/* ---------------- Phase checks (auto-pass missing) ---------------- */

function checkScale(programMap, scaleKey, submissionValue) {
  const allowed = programMap.get(normStr(scaleKey));
  if (!allowed || allowed.size === 0) return { enforced: false, pass: true };

  const sv = String(submissionValue ?? "").trim();
  if (!sv) return { enforced: true, pass: true, missingSubmission: true, allowed: Array.from(allowed) };

  const pass = allowed.has(normStr(sv));
  return { enforced: true, pass, allowed: Array.from(allowed), actual: sv };
}

function phase1_location(sub, prog, omissionsByProgram) {
  // State
  {
    const r = checkScale(prog.serviceArea, "state", sub.location.state);
    if (!r.enforced) addOmission(omissionsByProgram, prog, "phase1📍", "program omitted state restriction");
    else if (r.missingSubmission) addOmission(omissionsByProgram, prog, "phase1📍", "submission missing state (auto-pass)");
    else if (!r.pass) return { pass: false, fails: [{ check:"state", actual:r.actual, allowed:r.allowed }] };
  }

  // County
  {
    const r = checkScale(prog.serviceArea, "county", sub.location.county);
    if (!r.enforced) addOmission(omissionsByProgram, prog, "phase1📍", "program omitted county restriction");
    else if (r.missingSubmission) addOmission(omissionsByProgram, prog, "phase1📍", "submission missing county (auto-pass)");
    else if (!r.pass) return { pass: false, fails: [{ check:"county", actual:r.actual, allowed:r.allowed }] };
  }

  // City / town
  {
    const cityAllowed = prog.serviceArea.get("city");
    const townAllowed = prog.serviceArea.get("town");
    const enforced = (cityAllowed && cityAllowed.size) || (townAllowed && townAllowed.size);

    if (!enforced) {
      addOmission(omissionsByProgram, prog, "phase1📍", "program omitted city/town restriction");
    } else {
      const sv = String(sub.location.city ?? "").trim();
      if (!sv) {
        addOmission(omissionsByProgram, prog, "phase1📍", "submission missing city/town (auto-pass)");
      } else {
        const ok =
          (cityAllowed && cityAllowed.has(normStr(sv))) ||
          (townAllowed && townAllowed.has(normStr(sv)));
        if (!ok) {
          return {
            pass: false,
            fails: [{
              check: "city/town",
              actual: sv,
              allowed: [
                ...(cityAllowed ? Array.from(cityAllowed) : []),
                ...(townAllowed ? Array.from(townAllowed) : []),
              ],
            }],
          };
        }
      }
    }
  }

  // COA
  {
    const coaAllowed = prog.serviceArea.get("coa");
    if (!coaAllowed || !coaAllowed.size) {
      addOmission(omissionsByProgram, prog, "phase1📍", "program omitted coa restriction");
    } else {
      const wantTrue = coaAllowed.has("true") || coaAllowed.has("yes");
      if (sub.location.coa === null) {
        addOmission(omissionsByProgram, prog, "phase1📍", "submission missing coa (auto-pass)");
      } else if (wantTrue && sub.location.coa !== true) {
        return { pass: false, fails: [{ check:"coa", actual: sub.location.coa, expected:true }] };
      }
    }
  }

  // Neighborhood / legacy
  {
    const r = checkScale(prog.serviceArea, "neighborhood", sub.location.neighborhood);
    const r2 = checkScale(prog.serviceArea, "legacy", sub.location.neighborhood);
    const enforced = r.enforced || r2.enforced;

    if (!enforced) {
      addOmission(omissionsByProgram, prog, "phase1📍", "program omitted neighborhood/legacy restriction");
    } else {
      const sv = String(sub.location.neighborhood ?? "").trim();
      if (!sv) {
        addOmission(omissionsByProgram, prog, "phase1📍", "submission missing neighborhood/legacy (auto-pass)");
      } else {
        const allowed = [
          ...(prog.serviceArea.get("neighborhood") ? Array.from(prog.serviceArea.get("neighborhood")) : []),
          ...(prog.serviceArea.get("legacy") ? Array.from(prog.serviceArea.get("legacy")) : []),
        ];
        const ok = allowed.includes(normStr(sv));
        if (!ok) return { pass: false, fails: [{ check:"neighborhood/legacy", actual: sv, allowed }] };
      }
    }
  }

  return { pass: true };
}

function phase2_income(sub, prog, omissionsByProgram) {
  const { calc, max } = prog.incomeRule;
  if (!calc || !Number.isFinite(max)) {
    addOmission(omissionsByProgram, prog, "phase2💲", "program omitted income rule");
    return { pass: true };
  }

  const pct = sub.incomeMap[calc];
  if (!Number.isFinite(pct)) {
    addOmission(omissionsByProgram, prog, "phase2💲", `submission missing ${calc}% (auto-pass)`);
    return { pass: true };
  }

  if (pct <= max) return { pass: true };
  return { pass: false, fails: [{ check:`income:${calc}`, actual:pct, expected:`<= ${max}` }] };
}

function ownershipRulePasses(sub, prog, rule, omissionsByProgram) {
  const fails = [];

  // typeHome list
  if (Array.isArray(rule.typeHome) && rule.typeHome.length) {
    const sv = String(sub.ownership.typeHome ?? "").trim();
    if (!sv) {
      addOmission(omissionsByProgram, prog, "phase3🏡", "submission missing typeHome (auto-pass)");
    } else {
      const allowed = rule.typeHome.map(normStr);
      if (!allowed.includes(normStr(sv))) fails.push({ check:"typeHome", actual: sv, allowed: rule.typeHome });
    }
  } else {
    addOmission(omissionsByProgram, prog, "phase3🏡", "program omitted typeHome restriction");
  }

  // bldgValue max
  if (rule.bldgValue !== undefined && rule.bldgValue !== null && String(rule.bldgValue) !== "") {
    const maxVal = toNumber(rule.bldgValue);
    const subVal = sub.ownership.bldgValue;
    if (!Number.isFinite(subVal)) {
      addOmission(omissionsByProgram, prog, "phase3🏡", "submission missing bldgValue (auto-pass)");
    } else if (Number.isFinite(maxVal) && subVal > maxVal) {
      fails.push({ check:"bldgValue", actual: subVal, expected:`<= ${maxVal}` });
    }
  } else {
    addOmission(omissionsByProgram, prog, "phase3🏡", "program omitted bldgValue restriction");
  }

  // booleans
  for (const k of ["primaryRes","ownHome","ownLot"]) {
    if (rule[k] === true || rule[k] === false) {
      if (sub.ownership[k] === null) {
        addOmission(omissionsByProgram, prog, "phase3🏡", `submission missing ${k} (auto-pass)`);
      } else if (sub.ownership[k] !== rule[k]) {
        fails.push({ check:k, actual: sub.ownership[k], expected: rule[k] });
      }
    } else {
      addOmission(omissionsByProgram, prog, "phase3🏡", `program omitted ${k} restriction`);
    }
  }

  // minTime
  if (rule.minTime !== undefined && rule.minTime !== null && String(rule.minTime) !== "") {
    const minT = toNumber(rule.minTime);
    const subT = sub.ownership.minTime;
    if (!Number.isFinite(subT)) {
      addOmission(omissionsByProgram, prog, "phase3🏡", "submission missing minTime (auto-pass)");
    } else if (Number.isFinite(minT) && subT < minT) {
      fails.push({ check:"minTime", actual: subT, expected:`>= ${minT}` });
    }
  } else {
    addOmission(omissionsByProgram, prog, "phase3🏡", "program omitted minTime restriction");
  }

  // optional owner match
  if (CONFIG.enforceOwnerMatchWhenOwnHomeRequired && rule.ownHome === true) {
    const a = normStr(sub.applicantName);
    const o = normStr(sub.gisOwner);
    if (!a || !o) {
      addOmission(omissionsByProgram, prog, "phase3🏡", "submission missing applicantName or gisOwner (auto-pass owner match)");
    } else {
      const aTok = new Set(a.split(" ").filter(t => t.length >= 3));
      const oTok = new Set(o.split(" ").filter(t => t.length >= 3));
      let hit = 0;
      for (const t of aTok) if (oTok.has(t)) hit++;
      if (hit < 1) fails.push({ check:"gisOwner vs applicantName", applicantName: sub.applicantName, gisOwner: sub.gisOwner });
    }
  }

  return { pass: fails.length === 0, fails };
}

function phase3_ownership(sub, prog, omissionsByProgram) {
  if (!prog.ownershipChecks.length) {
    addOmission(omissionsByProgram, prog, "phase3🏡", "program omitted ownership rules entirely");
    return { pass: true };
  }

  const attempts = prog.ownershipChecks.map(rule => ownershipRulePasses(sub, prog, rule, omissionsByProgram));
  if (attempts.some(a => a.pass)) return { pass: true };
  return { pass: false, fails: attempts.flatMap(a => a.fails || []) };
}

function phase4_demo(sub, prog, omissionsByProgram) {
  if (!prog.demoRule) {
    addOmission(omissionsByProgram, prog, "phase4👤", "program omitted demographic rule");
    return { pass: true };
  }

  const { qual, codes } = prog.demoRule;
  const hits = codes.filter(c => sub.demoSet.has(c));

  if (qual.toLowerCase() === "required") {
    if (!sub.demoSet || sub.demoSet.size === 0) {
      addOmission(omissionsByProgram, prog, "phase4👤", "submission missing demo flags (auto-pass required demo)");
      return { pass: true };
    }

    if (CONFIG.demoRequiredMode === "all") {
      const pass = hits.length === codes.length;
      return pass ? { pass: true } : { pass: false, fails: [{ check:"demo(required:all)", required: codes, hits }] };
    } else {
      const pass = hits.length > 0;
      return pass ? { pass: true } : { pass: false, fails: [{ check:"demo(required:any)", required: codes, hits }] };
    }
  }

  return { pass: true, prioritized: true, hits, required: codes };
}

/* ---------------- Fail reporting helpers ---------------- */

function tallyFailChecks(failArray) {
  const counts = {};
  for (const row of (failArray || [])) {
    for (const f of (row.fails || [])) {
      const k = String(f.check || "unknown");
      counts[k] = (counts[k] || 0) + 1;
    }
  }
  return Object.entries(counts).sort((a,b) => b[1] - a[1]);
}

function formatTopFailChecks(failArray, limit = 10) {
  const tallied = tallyFailChecks(failArray).slice(0, limit);
  if (!tallied.length) return "(none)";
  return tallied.map(([k, n]) => `- ${k}: ${n}`).join("\n");
}

function formatFailExamples(failArray, limitPrograms = 5) {
  const slice = (failArray || []).slice(0, limitPrograms);
  if (!slice.length) return "(none)";
  return slice.map(x => {
    const first = (x.fails || [])[0] || {};
    const extra =
      first.expected !== undefined ? ` expected ${first.expected}` :
      first.allowed ? ` allowed ${JSON.stringify(first.allowed)}` : "";
    const got = first.actual !== undefined ? ` got ${JSON.stringify(first.actual)}` : "";
    return `- ${x.program}: ${first.check || "unknown"}${extra}${got}`;
  }).join("\n");
}

/* ---------------- ✅ NEW: Fail reasons (by program) ---------------- */

function addFailsByProgram(failsByProgram, phaseLabel, failArray) {
  for (const row of (failArray || [])) {
    const pid = row.programId || row.programID || row.id;
    if (!pid) continue;

    if (!failsByProgram[pid]) {
      failsByProgram[pid] = {
        program: row.program || "(unknown program)",
        programId: pid,
        phases: {},
      };
    }

    if (!failsByProgram[pid].phases[phaseLabel]) failsByProgram[pid].phases[phaseLabel] = [];
    failsByProgram[pid].phases[phaseLabel].push(...(row.fails || []));
  }
}

function formatOneFail(f) {
  if (!f || typeof f !== "object") return String(f);

  const parts = [];
  parts.push(String(f.check || "unknown"));

  if ("expected" in f) parts.push(`expected: ${JSON.stringify(f.expected)}`);
  if ("allowed" in f) parts.push(`allowed: ${JSON.stringify(f.allowed)}`);
  if ("actual" in f) parts.push(`actual: ${JSON.stringify(f.actual)}`);

  if ("required" in f) parts.push(`required: ${JSON.stringify(f.required)}`);
  if ("hits" in f) parts.push(`hits: ${JSON.stringify(f.hits)}`);

  if ("applicantName" in f) parts.push(`applicantName: ${JSON.stringify(f.applicantName)}`);
  if ("gisOwner" in f) parts.push(`gisOwner: ${JSON.stringify(f.gisOwner)}`);

  return parts.join(" | ");
}

function formatFailsByProgramText(failsByProgram) {
  const progs = Object.values(failsByProgram || {})
    .sort((a, b) => String(a.program).localeCompare(String(b.program)));

  if (!progs.length) return "(none)";

  return progs.map(p => {
    const phaseBlocks = Object.entries(p.phases || {})
      .filter(([, arr]) => Array.isArray(arr) && arr.length)
      .map(([phase, arr]) => {
        const lines = arr.map(x => `  - ${formatOneFail(x)}`).join("\n");
        return `${phase}:\n${lines}`;
      })
      .join("\n");

    return `[${p.program}] (${p.programId})\n${phaseBlocks || "(no fails recorded)"}`;
  }).join("\n\n");
}

function clampText(s, maxChars = 90000) {
  const str = String(s ?? "");
  if (str.length <= maxChars) return str;
  return str.slice(0, maxChars - 40) + "\n...(truncated due to length)";
}
[
  "phase1_locationPass",
  "phase2_incomePass",
  "phase3_ownerPass",
  "phase4_demoPass",
  "phase1_locationFail",
  "phase2_incomeFail",
  "phase3_ownerFail",
  "phase4_demoFail",
  "omissionsByProgram",
  "failsByProgram",
  "submissionDebug",
  "eligibilityReport",
  "failReasonsByProgramText",
  "failReasonsByProgramJsonText",
  "locationDebug",
].forEach(name => output.set(name, ""));
/* ---------------- MAIN ---------------- */

const omissionsByProgram = {};

// fail arrays
const phase1_locationFail = [];
const phase2_incomeFail = [];
const phase3_ownerFail = [];
const phase4_demoFail = [];

// Load submission
const subRec = await subTable.selectRecordAsync(submissionRecordId, {
  fields: Object.values(SUB_FIELDS).filter(Boolean),
});
if (!subRec) throw new Error(`Submission record not found: ${submissionRecordId}`);

const sub = normalizeSubmission(subRec);
//output.set("locationDebug", sub.location);

// Load programs once
const programIds = new Set(toIdArray(programsFound));
const progQuery = await progTable.selectRecordsAsync({
  fields: Object.values(PROG_FIELDS),
});
const allPrograms = progQuery.records
  .filter(r => programIds.size === 0 || programIds.has(r.id))
  .map(normalizeProgram);

// Phase 1 📍
const phase1_locationPass = [];
const phase1Programs = [];
for (const p of allPrograms) {
  const r = phase1_location(sub, p, omissionsByProgram);
  if (r.pass) {
    phase1_locationPass.push({ program: p.name, programId: p.id });
    phase1Programs.push(p);
  } else {
    phase1_locationFail.push({ program: p.name, programId: p.id, fails: r.fails || [] });
  }
}

// Phase 2 💲
const phase2_incomePass = [];
const phase2Programs = [];
for (const p of phase1Programs) {
  const r = phase2_income(sub, p, omissionsByProgram);
  if (r.pass) {
    phase2_incomePass.push({ program: p.name, programId: p.id });
    phase2Programs.push(p);
  } else {
    phase2_incomeFail.push({ program: p.name, programId: p.id, fails: r.fails || [] });
  }
}

// Phase 3 🏡
const phase3_ownerPass = [];
const phase3Programs = [];
for (const p of phase2Programs) {
  const r = phase3_ownership(sub, p, omissionsByProgram);
  if (r.pass) {
    phase3_ownerPass.push({ program: p.name, programId: p.id });
    phase3Programs.push(p);
  } else {
    phase3_ownerFail.push({ program: p.name, programId: p.id, fails: r.fails || [] });
  }
}

// Phase 4 👤
const phase4_demoPass = [];
for (const p of phase3Programs) {
  const r = phase4_demo(sub, p, omissionsByProgram);
  if (r.pass) {
    phase4_demoPass.push({ program: p.name, programId: p.id, prioritized: !!r.prioritized });
  } else {
    phase4_demoFail.push({ program: p.name, programId: p.id, fails: r.fails || [] });
  }
}

// ✅ NEW: Fail reasons by program (merged across phases)
const failsByProgram = {};
addFailsByProgram(failsByProgram, "phase1📍", phase1_locationFail);
addFailsByProgram(failsByProgram, "phase2💲", phase2_incomeFail);
addFailsByProgram(failsByProgram, "phase3🏡", phase3_ownerFail);
addFailsByProgram(failsByProgram, "phase4👤", phase4_demoFail);

const failReasonsByProgramText = clampText(formatFailsByProgramText(failsByProgram));
const failReasonsByProgramJsonText = clampText(JSON.stringify(failsByProgram, null, 2));

// Report
const qualifiedNames = phase4_demoPass.map(x => x.program);

const omittedLines = Object.values(omissionsByProgram)
  .map(o => `\n[${o.program}]\n- ` + o.items.join("\n- "))
  .join("\n");

const failSummary =
  `\n---\nFail check summary (count of programs failing each check):\n` +
  `\nPhase1📍:\n${formatTopFailChecks(phase1_locationFail)}` +
  `\n\nPhase2💲:\n${formatTopFailChecks(phase2_incomeFail)}` +
  `\n\nPhase3🏡:\n${formatTopFailChecks(phase3_ownerFail)}` +
  `\n\nPhase4👤:\n${formatTopFailChecks(phase4_demoFail)}` +
