});
if (!subRec) throw new Error(`Submission record not found: ${submissionRecordId}`);

const sub = normalizeSubmission(subRec);
//output.set("locationDebug", sub.location);

// Load programs once
const programIds = new Set(toIdArray(programsFound));
const progQuery = await progTable.selectRecordsAsync({
